import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

// Extended Generators including composite identities for specific axis control
const GENERATORS = [3, 5, 7, 9, 11, 13, 15];
const GENERATOR_RATIOS: Record<number, Fraction> = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  9: new Fraction(9, 8),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
  15: new Fraction(15, 8),
};

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 
  const maxDist = settings.latticeMaxDistance !== undefined ? settings.latticeMaxDistance : 12;

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      GENERATORS.forEach((gen, idx) => {
          const val = origin.coords[idx] || 0;
          const gRat = GENERATOR_RATIOS[gen];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(gRat).normalize() : originFrac.mul(new Fraction(gRat.d, gRat.n)).normalize();
          }
      });

      // Ensure origin coords has full length
      const fullCoords = [...origin.coords];
      while(fullCoords.length < GENERATORS.length) fullCoords.push(0);

      localQueue.push({ coords: fullCoords, ratio: originFrac });
      const visitedLocal = new Set<string>([fullCoords.join(',')]);

      const MAX_LOCAL_NODES = 1200; 
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          GENERATORS.forEach((gen, idx) => {
              // @ts-ignore - Safe access as keys are numbers
              const depthLimit = settings.limitDepths[gen];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  const originVal = origin.coords[idx] || 0;
                  // 1. Per-Axis Depth Check
                  if (Math.abs(nextCoords[idx] - originVal) > depthLimit) return;

                  // 2. Global Distance Check (Sum of absolute distances from origin on all axes)
                  // Use robust distance sum from origin
                  let dist = 0;
                  nextCoords.forEach((v, i) => dist += Math.abs(v - (origin.coords[i] || 0)));
                  if (dist > maxDist) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const gRat = GENERATOR_RATIOS[gen];
                      const nextFrac = dir === 1 ? current.ratio.mul(gRat).normalize() : current.ratio.mul(new Fraction(gRat.d, gRat.n)).normalize();

                      // 3. Complexity Check (Ratio Magnitude)
                      // @ts-ignore
                      const compLimit = (settings.limitComplexities && settings.limitComplexities[gen]) ? settings.limitComplexities[gen] : 1000;
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      // 1. Generate Octave Lines (Vertical/Limit 2)
      // Connect to the node exactly one octave up if it exists
      const octaveTargetId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octaveTarget = nodesMap.get(octaveTargetId);
      if (octaveTarget) {
          lines.push({
              id: `${node.id}-${octaveTarget.id}`,
              x1: node.x, y1: node.y, x2: octaveTarget.x, y2: octaveTarget.y,
              limit: 2, // Limit 2 = Octave
              sourceId: node.id, targetId: octaveTarget.id
          });
      }

      // 2. Generate Prime Generator Lines
      GENERATORS.forEach((gen, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          // Check neighbors in adjacent octaves to handle spiral/complex reductions
          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  // Validate geometric connection logic (ratio consistency)
                  const ratio = target.ratio / node.ratio;
                  const genRat = GENERATOR_RATIOS[gen];
                  const targetVal = genRat.n / genRat.d;

                  // Allow octave equivalency for connection validation
                  const normalizedRatio = ratio >= 1 ? ratio : 1/ratio; 
                  // Simple log check is sufficient for 2-limit equivalence
                  const test = Math.log2(normalizedRatio / targetVal);

                  // Allow connection if ratio matches generator ratio modulo octaves
                  if (Math.abs(test - Math.round(test)) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: gen, 
                          sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond based on enabled Identities
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Use user-defined identities from settings (e.g. [1, 3, 5, 7, 9, 11])
    // Filter out hidden ones if they are in the list but hidden (optional, but good for consistency)
    const activeIdentities = (settings.enabledIdentities || [1, 3, 5]).filter(id => !settings.hiddenLimits.includes(id));

    // Sort numerically to ensure consistent grid structure
    activeIdentities.sort((a, b) => a - b);

    // Ensure 1 is always present for the root
    if (!activeIdentities.includes(1)) activeIdentities.unshift(1);

    const N = activeIdentities.length;
    // Updated Spacing: Reduced from 200 to 100 to match standard lattice vectors (1.0 base scale)
    const diamondSpacing = 100; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Stable ID based on Identities
            const id = `diamond-${idOton}-${idUton}`;

            // Layout indices rotated 45 degrees
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            nodes.push({
                id,
                // Store grid indices in coords for potential neighbor logic, though graph is explicit here
                coords: [o, u, 0, 0, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y,
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node) => {
        const [o, u] = node.coords;
        nodes.forEach((target) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);

            // Check for immediate neighbors in the grid (Manhattan distance 1 in O-U space)
            // (1 step Otonal OR 1 step Utonal)
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; // Maps NodeID -> Lowest Limit connecting to it
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

// Render Order Priority (Highest = Topmost/Outer Ring)
const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, // Cursor
    3: 1, // Strum
    2: 2, // Strings
    4: 3, // Brass
    5: 4, // Keys
    'arp': 5, // Arp
    1: 6  // Drone (Top)
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(staticCanvas, state);
        this.renderDynamic(bgCanvas, activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return {
                    bg: '#f8fafc', // Slate-50
                    line: '#94a3b8', // Slate-400
                    lineDim: 'rgba(148, 163, 184, 0.2)',
                    nodeText: '#334155', // Slate-700
                    nodeStroke: '#334155',
                    nodeFill: () => '#ffffff',
                    shadow: 'rgba(0,0,0,0.1)'
                };
            case 'blueprint':
                return {
                    bg: '#1e3a8a', // Blue-900
                    line: 'rgba(147, 197, 253, 0.4)', // Blue-300
                    lineDim: 'rgba(147, 197, 253, 0.1)',
                    nodeText: '#dbeafe', // Blue-100
                    nodeStroke: '#93c5fd',
                    nodeFill: () => '#172554', // Blue-950
                    shadow: 'rgba(0,0,0,0.3)'
                };
            case 'cyber':
                return {
                    bg: '#000000',
                    line: '#333333',
                    lineDim: '#111111',
                    nodeText: '#ffffff',
                    nodeStroke: '#444444',
                    nodeFill: () => '#000000',
                    shadow: '#00ff00'
                };
            case 'default':
            default:
                return {
                    bg: 'transparent',
                    line: '#666',
                    lineDim: 'rgba(255,255,255,0.1)',
                    nodeText: '#ffffff',
                    nodeStroke: 'transparent',
                    nodeFill: (limit, map) => map[limit] || '#666',
                    shadow: 'black'
                };
        }
    }

    private renderStatic(canvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            linesLen: data.lines.length,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (canvas.width !== view.w * dpr || canvas.height !== view.h * dpr) {
            canvas.width = view.w * dpr;
            canvas.height = view.h * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);

        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;

            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = Math.max(0, baseRadius * limitScale);

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                // Default Gradient
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop);
                grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad;
                ctx.fill();
            }

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = skin.nodeText;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale;
                    ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,${0.8 * limitOpacity})`;
                    if (settings.activeSkin === 'cyber') ctx.strokeStyle = '#fff';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(bgCanvas: HTMLCanvasElement, activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time, latchMode 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (bgCanvas.width !== view.w * dpr || bgCanvas.height !== view.h * dpr) {
            bgCanvas.width = view.w * dpr;
            bgCanvas.height = view.h * dpr;
            activeCanvas.width = view.w * dpr;
            activeCanvas.height = view.h * dpr;
        }

        bgCtx.setTransform(1, 0, 0, 1, 0, 0);
        activeCtx.setTransform(1, 0, 0, 1, 0, 0);

        // Clear only viewport
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
        activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);

        // Transform
        bgCtx.scale(dpr, dpr);
        activeCtx.scale(dpr, dpr);
        bgCtx.translate(-view.x, -view.y);
        activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const animationSpeed = (settings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = settings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        bgCtx.lineCap = 'round';
        activeCtx.lineCap = 'round';

        // 0. Draw Harmonic Neighbor Hints
        if (harmonicNeighbors.size > 0) {
            for (const [id, limit] of harmonicNeighbors.entries()) {
                const node = this.cachedNodeMap.get(id);
                if (!node) continue;

                const x = node.x * spacing + centerOffset;
                const y = node.y * spacing + centerOffset;

                if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

                const color = settings.colors[limit] || '#ffffff';
                const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                const limitScale = vis.size;
                const radius = Math.max(0, baseRadius * limitScale * 1.3);

                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(x, y - radius);
                    activeCtx.lineTo(x + radius, y);
                    activeCtx.lineTo(x, y + radius);
                    activeCtx.lineTo(x - radius, y);
                } else {
                    activeCtx.arc(x, y, radius, 0, Math.PI * 2);
                }
                activeCtx.closePath();

                activeCtx.lineWidth = 3 * effectiveScale;
                activeCtx.strokeStyle = color;
                activeCtx.globalAlpha = 0.6;
                activeCtx.stroke();

                activeCtx.fillStyle = color;
                activeCtx.globalAlpha = 0.15;
                activeCtx.fill();
            }
        }

        // 1. Draw Brightened Lines (Voice Leading)
        // Ensure gradient always flows OUT from the active node to prevent lopsided visuals.
        if (brightenedLines.length > 0) {
            bgCtx.setLineDash([]);
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                let limitColor = settings.colors[line.limit] || '#666';
                if (isFlatSkin) limitColor = skin.line;

                // Base Line
                bgCtx.beginPath();
                bgCtx.moveTo(x1, y1);
                bgCtx.lineTo(x2, y2);
                bgCtx.lineWidth = (settings.lineBrighteningWidth || 1.0) * effectiveScale;
                bgCtx.strokeStyle = limitColor;
                bgCtx.globalAlpha = isFlatSkin ? 0.6 : 0.8; 
                bgCtx.stroke();

                // Animation Layer
                if (settings.isVoiceLeadingAnimationEnabled) {
                    // Determine directionality
                    const isSourceActive = visualLatchedNodes.has(line.sourceId);
                    const isTargetActive = visualLatchedNodes.has(line.targetId);

                    // Logic: Pulse flows OUT from active node.
                    // If target is active but source is not, flip the gradient so it flows Target -> Source (Outward)
                    // If source is active, flow Source -> Target (Outward)
                    // If both, default to Source -> Target (or could animate both ways, but one way is usually cleaner)
                    let sx = x1, sy = y1, ex = x2, ey = y2;
                    if (isTargetActive && !isSourceActive) {
                        sx = x2; sy = y2; ex = x1; ey = y1;
                    }

                    const grad = bgCtx.createLinearGradient(sx, sy, ex, ey);
                    const p = flowPhase;
                    const bright = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.85)';
                    const clear = 'rgba(255,255,255,0)';

                    grad.addColorStop(0, clear);
                    const pulseWidth = 0.25; // Wider pulse for better visibility
                    const start = Math.max(0, p - pulseWidth);
                    const end = Math.min(1, p + pulseWidth);
                    if (start > 0) grad.addColorStop(start, clear);
                    grad.addColorStop(p, bright); 
                    if (end < 1) grad.addColorStop(end, clear);
                    grad.addColorStop(1, clear);

                    bgCtx.strokeStyle = grad;
                    // Boost the glow width and alpha for better visibility
                    bgCtx.lineWidth = 12 * (0.5 + settings.voiceLeadingGlowAmount) * effectiveScale;
                    bgCtx.globalAlpha = 0.4; 
                    bgCtx.stroke();

                    bgCtx.lineWidth = 4 * effectiveScale;
                    bgCtx.globalAlpha = 1.0;
                    bgCtx.stroke();
                }
            }
        }

        // 2. Draw Active Lines (Fully Connected)
        bgCtx.setLineDash([]); 
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            let limitColor = settings.colors[line.limit] || '#666';
            if (isFlatSkin) limitColor = skin.nodeStroke;

            bgCtx.beginPath();
            bgCtx.moveTo(x1, y1);
            bgCtx.lineTo(x2, y2);
            bgCtx.lineWidth = (isFlatSkin ? 2 : 4) * effectiveScale;
            bgCtx.strokeStyle = limitColor;
            bgCtx.globalAlpha = 1.0;
            bgCtx.stroke();
        }

        // 3. Draw Active Nodes
        for (const [id, activations] of visualLatchedNodes.entries()) {
             const node = this.cachedNodeMap.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const cBottom = settings.colors[node.limitBottom] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = settings.latchedZoomScale;
             const baseRad = Math.max(0, baseRadius * limitScale * zoomScale);

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - baseRad);
                activeCtx.lineTo(x + baseRad, y);
                activeCtx.lineTo(x, y + baseRad);
                activeCtx.lineTo(x - baseRad, y);
             } else {
                activeCtx.arc(x, y, baseRad, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isFlatSkin) {
                 activeCtx.fillStyle = '#ffffff'; 
                 if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#000000';
                 if (settings.activeSkin === 'blueprint') activeCtx.fillStyle = '#dbeafe';
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - baseRad, x, y + baseRad);
                 grad.addColorStop(0.45, cTop);
                 grad.addColorStop(0.55, cBottom);
                 activeCtx.fillStyle = grad;
             }
             activeCtx.fill();

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));

             const sortedModes = Array.from(uniqueModes).sort((a, b) => {
                 return (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99);
             });

             const ringWidth = 4 * effectiveScale;
             const ringGap = 2 * effectiveScale;

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';

                 // Strum Ripple
                 if (mode === 3 || mode === 'arp') {
                     const activation = activations.find(a => a.mode === mode);
                     if (activation) {
                         const age = time - activation.timestamp;
                         if (age < 500) { 
                             const rippleProgress = age / 500;
                             const rippleRadius = Math.max(0, baseRad + (rippleProgress * 40 * effectiveScale));
                             const rippleAlpha = 1.0 - rippleProgress;

                             activeCtx.beginPath();
                             activeCtx.arc(x, y, rippleRadius, 0, Math.PI * 2);
                             activeCtx.strokeStyle = color;
                             activeCtx.lineWidth = 2 * effectiveScale;
                             activeCtx.globalAlpha = rippleAlpha;
                             activeCtx.stroke();
                         }
                     }
                 }

                 const currentRadius = Math.max(0, baseRad + ringGap + (index * (ringWidth + ringGap)));

                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius);
                    activeCtx.lineTo(x + currentRadius, y);
                    activeCtx.lineTo(x, y + currentRadius);
                    activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();

                 activeCtx.strokeStyle = color;
                 activeCtx.lineWidth = ringWidth;
                 activeCtx.globalAlpha = 0.8;

                 activeCtx.shadowBlur = 8 * effectiveScale;
                 activeCtx.shadowColor = color;
                 activeCtx.stroke();
                 activeCtx.shadowBlur = 0;
             });

             const combinedScale = settings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = isFlatSkin ? skin.nodeStroke : 'white';
                if (settings.activeSkin === 'cyber') activeCtx.fillStyle = '#00ff00';

                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (baseRad * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (baseRad * 0.4), y);
                    activeCtx.lineTo(x + (baseRad * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale;
                    activeCtx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.5)' : 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (baseRad * spacingY));
             }
        }

        // 4. Draw Cursors
        if (settings.isPitchBendEnabled && latchMode !== 3) {
            activeCursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = this.cachedNodeMap.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset;
                         const pos = cursorPositions.get(c.pointerId);
                         if (!pos) return;

                         const cx = pos.x;
                         const cy = pos.y;

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isFlatSkin ? skin.nodeStroke : 'white';
                         activeCtx.lineWidth = 2 * effectiveScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
        }
    }
}

import React from 'react';
import { AppSettings, TuningSystem, LayoutApproach } from '../../types';
import { NumberInput } from './SettingsWidgets';

interface Props {
    settings: AppSettings;
    updateSettings: (s: Partial<AppSettings>) => void;
}

const PRIMES = [3, 5, 7, 9, 11, 13, 15];

const TonalityTab: React.FC<Props> = ({ settings, updateSettings }) => {

    const handleChange = (key: keyof AppSettings, value: any) => updateSettings({ [key]: value });

    const handleLimitDepthChange = (limit: number, val: number) => {
        // @ts-ignore
        updateSettings({ limitDepths: { ...settings.limitDepths, [limit]: val } });
    };

    const handleLimitComplexityChange = (limit: number, val: number) => {
        // @ts-ignore
        updateSettings({ limitComplexities: { ...settings.limitComplexities, [limit]: val } });
    };

    const renderLayoutSelector = (system: TuningSystem) => {
        let options: { value: LayoutApproach; label: string }[] = [];

        switch (system) {
          case 'ji':
            options = [
              { value: 'lattice', label: 'Tonality Lattice' },
              { value: 'diamond', label: 'Tonality Diamond' },
            ];
            break;
          case 'et':
            options = [
              { value: 'et_wheel', label: 'Chromatic Wheel' },
              { value: 'et_grid', label: 'Keyboard Grid' },
              { value: 'et_row', label: 'Linear Strip' },
            ];
            break;
          case 'indian':
            options = [
              { value: 'indian_circle', label: 'Shruti Circle' },
              { value: 'indian_thaat', label: 'Thaat Map' },
            ];
            break;
          case 'pythagorean':
            options = [
              { value: 'pyth_spiral', label: 'Spiral of Fifths' },
              { value: 'pyth_row', label: 'Linear Stack' },
            ];
            break;
        }

        const isValid = options.some(o => o.value === settings.layoutApproach);
        if (!isValid && options.length > 0) {
          setTimeout(() => handleChange('layoutApproach', options[0].value), 0);
        }

        return (
          <div className="bg-slate-900/60 p-4 rounded-lg border border-indigo-500/20 mb-6">
              <label className="block text-[10px] text-indigo-400 font-bold uppercase mb-2 tracking-widest">Layout & Orientation</label>
              <div className="flex gap-2">
                  <select 
                      value={settings.layoutApproach} 
                      onChange={(e) => {
                          const newLayout = e.target.value as LayoutApproach;
                          let newSpacing = settings.buttonSpacingScale;

                          if (newLayout === 'diamond') newSpacing = 0.756; 
                          else if (newLayout === 'lattice') newSpacing = 1.89; 

                          updateSettings({ 
                              layoutApproach: newLayout,
                              buttonSpacingScale: newSpacing
                          });
                      }}
                      className="flex-1 bg-slate-800 border border-slate-600 rounded p-1.5 text-[10px] text-white focus:outline-none focus:border-indigo-500"
                  >
                      {options.map(opt => (
                        <option key={opt.value} value={opt.value}>{opt.label}</option>
                      ))}
                  </select>
              </div>
              <p className="text-[9px] text-slate-500 mt-2 italic">Governs the geometric arrangement and orientation of pitch nodes.</p>
          </div>
        );
