// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

export const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const GENERATORS = [3, 5, 7, 9, 11, 13, 15];
const GENERATOR_RATIOS: Record<number, Fraction> = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  9: new Fraction(9, 8),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
  15: new Fraction(15, 8),
};

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const lines: LatticeLine[] = [];
  const OCTAVE_RANGE = 2; 
  const maxDist = settings.latticeMaxDistance !== undefined ? settings.latticeMaxDistance : 12;

  // The latest origin in the path is the "Active" one
  const activeOriginIndex = generationOrigins.length - 1;

  generationOrigins.forEach((origin, oIdx) => {
      const isGhost = oIdx !== activeOriginIndex;
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate absolute start ratio for origin coords relative to global 1/1
      let originFrac = new Fraction(1, 1);
      GENERATORS.forEach((gen, idx) => {
          const val = origin.coords[idx] || 0;
          const gRat = GENERATOR_RATIOS[gen];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(gRat).normalize() : originFrac.mul(new Fraction(gRat.d, gRat.n)).normalize();
          }
      });
      // Adjust for base octave
      originFrac = originFrac.shiftOctave(origin.octave);

      const fullCoords = [...origin.coords];
      while(fullCoords.length < GENERATORS.length) fullCoords.push(0);

      localQueue.push({ coords: fullCoords, ratio: originFrac });
      const visitedLocal = new Set<string>([fullCoords.join(',')]);

      // Reduce complexity limits for ghost lattices to save performance
      const MAX_LOCAL_NODES = isGhost ? 100 : 1200; 
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct - origin.octave);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct,
                      isGhost: isGhost,
                      originIndex: oIdx
                  });
              }
          }

          GENERATORS.forEach((gen, idx) => {
              // @ts-ignore
              const depthLimit = settings.limitDepths[gen];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  const originVal = origin.coords[idx] || 0;
                  if (Math.abs(nextCoords[idx] - originVal) > depthLimit) return;

                  let dist = 0;
                  nextCoords.forEach((v, i) => dist += Math.abs(v - (origin.coords[i] || 0)));
                  if (dist > maxDist) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const gRat = GENERATOR_RATIOS[gen];
                      const nextFrac = dir === 1 ? current.ratio.mul(gRat).normalize() : current.ratio.mul(new Fraction(gRat.d, gRat.n)).normalize();

                      visitedLocal.add(key);
                      localQueue.push({ coords: nextCoords, ratio: nextFrac });
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());

  nodes.forEach(node => {
      // 1. Generate Octave Lines (Vertical/Limit 2)
      const octaveTargetId = `${node.coords.join(',')}:${node.octave + 1}`;
      const octaveTarget = nodesMap.get(octaveTargetId);
      if (octaveTarget) {
          lines.push({
              id: `${node.id}-${octaveTarget.id}`,
              x1: node.x, y1: node.y, x2: octaveTarget.x, y2: octaveTarget.y,
              limit: 2, 
              sourceId: node.id, targetId: octaveTarget.id,
              isGhost: node.isGhost && octaveTarget.isGhost
          });
      }

      // 2. Generate Prime Generator Lines
      GENERATORS.forEach((gen, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const genRat = GENERATOR_RATIOS[gen];
                  const targetVal = genRat.n / genRat.d;
                  const normalizedRatio = ratio >= 1 ? ratio : 1/ratio; 
                  const test = Math.log2(normalizedRatio / targetVal);

                  if (Math.abs(test - Math.round(test)) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: gen, 
                          sourceId: node.id, targetId: target.id,
                          isGhost: node.isGhost && target.isGhost
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond based on enabled Identities
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    const activeIdentities = (settings.enabledIdentities || [1, 3, 5, 7, 9, 11, 13, 15]).filter(id => !settings.hiddenLimits.includes(id));
    activeIdentities.sort((a, b) => a - b);
    if (!activeIdentities.includes(1)) activeIdentities.unshift(1);

    const N = activeIdentities.length;
    const diamondSpacing = 100; 

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            const id = `diamond-${idOton}-${idUton}`;
            const x = ((o + u) - (N - 1)) * diamondSpacing;
            const y = (u - o) * diamondSpacing;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0, 0, 0], 
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x,
                y: y,
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    nodes.forEach((node) => {
        const [o, u] = node.coords;
        nodes.forEach((target) => {
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';
import { projectCoordinates } from './ProjectionService';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; 
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
}

const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, 
    3: 1, 
    2: 2, 
    4: 3, 
    5: 4, 
    'arp': 5, 
    1: 6  
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(staticCanvas, state);
        this.renderDynamic(bgCanvas, activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return { bg: '#f8fafc', line: '#94a3b8', lineDim: 'rgba(148, 163, 184, 0.2)', nodeText: '#334155', nodeStroke: '#334155', nodeFill: () => '#ffffff', shadow: 'rgba(0,0,0,0.1)' };
            case 'blueprint':
                return { bg: '#1e3a8a', line: 'rgba(147, 197, 253, 0.4)', lineDim: 'rgba(147, 197, 253, 0.1)', nodeText: '#dbeafe', nodeStroke: '#93c5fd', nodeFill: () => '#172554', shadow: 'rgba(0,0,0,0.3)' };
            case 'cyber':
                return { bg: '#000000', line: '#333333', lineDim: '#111111', nodeText: '#ffffff', nodeStroke: '#444444', nodeFill: () => '#000000', shadow: '#00ff00' };
            case 'default':
            default:
                return { bg: 'transparent', line: '#666', lineDim: 'rgba(255,255,255,0.1)', nodeText: '#ffffff', nodeStroke: 'transparent', nodeFill: (limit, map) => map[limit] || '#666', shadow: 'black' };
        }
    }

    private renderStatic(canvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            linesLen: data.lines.length,
            path: settings.modulationPath,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (canvas.width !== view.w * dpr || canvas.height !== view.h * dpr) {
            canvas.width = view.w * dpr;
            canvas.height = view.h * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Lines
        for (const line of data.lines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = (line.limit === 2 ? 3 : 1) * effectiveScale;
            ctx.strokeStyle = line.isGhost ? 'rgba(100,116,139,0.1)' : skin.line;
            ctx.stroke();
        }

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const radius = Math.max(0, baseRadius * topVis.size);

            if (node.isGhost) {
                // Ghost Node Trace
                ctx.globalAlpha = 0.2;
                ctx.strokeStyle = '#64748b';
                ctx.lineWidth = 1 * effectiveScale;
                ctx.beginPath();
                if (isDiamond) {
                    ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
                } else {
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                }
                ctx.closePath();
                ctx.stroke();
                ctx.globalAlpha = 1.0;
                continue; 
            }

            ctx.globalAlpha = 1.0 * topVis.opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad; ctx.fill();
            }

            if (settings.buttonSizeScale * topVis.size > 0.4) {
                ctx.fillStyle = skin.nodeText; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * settings.buttonSizeScale * topVis.size)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath(); ctx.moveTo(x - (radius * 0.4), y); ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale; ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,0.8)`;
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(bgCanvas: HTMLCanvasElement, activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, harmonicNeighbors,
            activeCursors, cursorPositions, effectiveScale, centerOffset, view, time 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (bgCanvas.width !== view.w * dpr || bgCanvas.height !== view.h * dpr) {
            bgCanvas.width = view.w * dpr; bgCanvas.height = view.h * dpr;
            activeCanvas.width = view.w * dpr; activeCanvas.height = view.h * dpr;
        }

        bgCtx.setTransform(1, 0, 0, 1, 0, 0); activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height); activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        bgCtx.scale(dpr, dpr); activeCtx.scale(dpr, dpr);
        bgCtx.translate(-view.x, -view.y); activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const cullPad = 200;
        const cullLeft = view.x - cullPad; const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad; const cullBottom = view.y + view.h + cullPad;

        bgCtx.lineCap = 'round'; activeCtx.lineCap = 'round';

        // --- DRAW MODULATION PATH ---
        if (settings.modulationPath.length > 1) {
            activeCtx.beginPath();
            settings.modulationPath.forEach((p, idx) => {
                let rat = Math.pow(2, p.octave);
                [3, 5, 7, 9, 11, 13, 15].forEach((gen, gIdx) => {
                   const val = p.coords[gIdx] || 0;
                   if (val !== 0) {
                       const gVal = [3/2, 5/4, 7/4, 9/8, 11/8, 13/8, 15/8][gIdx];
                       rat *= Math.pow(gVal, val);
                   }
                });
                const { x: px, y: py } = projectCoordinates(p.coords, rat, settings.latticeAspectRatio, 'lattice');
                const sx = px * spacing + centerOffset;
                const sy = py * spacing + centerOffset;

                if (idx === 0) activeCtx.moveTo(sx, sy);
                else activeCtx.lineTo(sx, sy);
            });
            activeCtx.lineWidth = 4 * effectiveScale;
            activeCtx.strokeStyle = '#22d3ee';
            activeCtx.setLineDash([10, 10]);
            activeCtx.lineDashOffset = -time * 0.05;
            activeCtx.stroke();
            activeCtx.setLineDash([]);
        }

        // 1. Draw Active Lines
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset; const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset; const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            bgCtx.beginPath(); bgCtx.moveTo(x1, y1); bgCtx.lineTo(x2, y2);
            bgCtx.lineWidth = 4 * effectiveScale;
            bgCtx.strokeStyle = settings.colors[line.limit] || '#666';
            bgCtx.globalAlpha = 1.0; bgCtx.stroke();
        }

        // 2. Draw Active Nodes
        for (const [id, activations] of visualLatchedNodes.entries()) {
             const node = this.cachedNodeMap.get(id);
             if (!node) continue;
             const x = node.x * spacing + centerOffset; const y = node.y * spacing + centerOffset;
             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const radius = Math.max(0, baseRadius * vis.size * settings.latchedZoomScale);

             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius); activeCtx.lineTo(x + radius, y); activeCtx.lineTo(x, y + radius); activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
             activeCtx.fillStyle = grad; activeCtx.fill();

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));
             const sortedModes = Array.from(uniqueModes).sort((a, b) => (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99));

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';
                 const currentRadius = radius + (2 * effectiveScale) + (index * 6 * effectiveScale);
                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius); activeCtx.lineTo(x + currentRadius, y); activeCtx.lineTo(x, y + currentRadius); activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();
                 activeCtx.strokeStyle = color; activeCtx.lineWidth = 4 * effectiveScale;
                 activeCtx.stroke();
             });
        }
    }
}

import { useState, useEffect, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import { generateLattice } from '../services/LatticeService';
import { GRID_CELL_SIZE } from '../constants';

export const useLatticeData = (settings: AppSettings, globalScale: number) => {
    const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
    const [isGenerating, setIsGenerating] = useState(false);
    const [dynamicSize, setDynamicSize] = useState(2000);

    const centerOffset = dynamicSize / 2;

    const nodeMap = useMemo(() => {
        return new Map(data.nodes.map(n => [n.id, n]));
    }, [data.nodes]);

    const spatialGrid = useMemo(() => {
        const grid = new Map<string, LatticeNode[]>();
        const spacing = settings.buttonSpacingScale * globalScale;

        data.nodes.forEach(node => {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            const col = Math.floor(x / GRID_CELL_SIZE);
            const row = Math.floor(y / GRID_CELL_SIZE);
            const key = `${col},${row}`;
            if (!grid.has(key)) grid.set(key, []);
            grid.get(key)!.push(node);
        });
        return grid;
    }, [data.nodes, settings.buttonSpacingScale, globalScale, centerOffset]);

    const adjacencyMap = useMemo(() => {
        const map = new Map<string, { target: string, limit: number }[]>();
        data.lines.forEach(line => {
            if (!map.has(line.sourceId)) map.set(line.sourceId, []);
            if (!map.has(line.targetId)) map.set(line.targetId, []);
            map.get(line.sourceId)!.push({ target: line.targetId, limit: line.limit });
            map.get(line.targetId)!.push({ target: line.sourceId, limit: line.limit });
        });
        return map;
    }, [data.lines]);

    const generationDeps = useMemo(() => {
        return JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            depths: settings.limitDepths,
            hidden: settings.hiddenLimits,
            ratio: settings.latticeAspectRatio,
            skin: settings.activeSkin,
            path: settings.modulationPath // Re-generate on modulation path change
        });
    }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin, settings.modulationPath]);

    useEffect(() => {
        setIsGenerating(true);
        const timerId = setTimeout(() => {
            // Pass the modulation path to generate traces
            const result = generateLattice(settings, settings.modulationPath);
            setData({ nodes: result.nodes, lines: result.lines });
            setIsGenerating(false);
        }, 10);
        return () => clearTimeout(timerId);
    }, [generationDeps]);

    useEffect(() => {
        if (data.nodes.length === 0) return;

        let maxExtent = 0;
        for (const n of data.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const spacing = settings.buttonSpacingScale * globalScale;
        const padding = 1000; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.min(Math.max(calculatedSize, 2000), 12000);

        if (Math.abs(finalSize - dynamicSize) > 100) {
            setDynamicSize(finalSize);
        }
    }, [data.nodes, settings.buttonSpacingScale, globalScale]);

    return { data, isGenerating, dynamicSize, nodeMap, spatialGrid, adjacencyMap, centerOffset };
};

