  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; // NEW: Track if this cursor is controlling a chord shift
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  // This happens when modulating away from a center but keeping notes latched.
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              // Try to reconstruct the node data from ID
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      // Also check active cursors if they are holding a node that disappeared
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          // Determine if we should show cursor glow
          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes); // NEW: Need this for shift calculation
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        if (settings.isModulationModeActive) {
            const newOrigin: GenerationOrigin = {
                coords: hitNode.coords,
                octave: hitNode.octave
            };

            const newPath = [...settings.modulationPath, newOrigin];

            const currentOrigin = settings.modulationPath[settings.modulationPath.length - 1];
            const isSame = currentOrigin.coords.every((v, i) => v === hitNode.coords[i]) && currentOrigin.octave === hitNode.octave;

            if (!isSame) {
                updateSettings({ 
                    modulationPath: newPath,
                    isModulationModeActive: false
                });
            }
            return; 
        }

        // --- SHIFT LOGIC (Initiate) ---
        const isShiftMode = settings.isShiftModeActive;
        const currentLatches = persistentLatchesRef.current;
        const isClickedLatched = currentLatches.has(hitNode.id);

        if (isShiftMode && isClickedLatched) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: true // Mark as anchor
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            return; // Don't trigger sound or normal latch logic
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                 const next = new Map(prev);
                 const nodeModes = next.get(hitNode.id) || new Map<number, number>();

                 if (nodeModes.has(latchMode)) {
                     nodeModes.delete(latchMode);
                 } else {
                     nodeModes.set(latchMode, Date.now());
                 }

                 if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                 else next.delete(hitNode.id);
                 return next;
             });
        }

        if ((isBendEnabled || !isSustainActive) && !isShiftMode) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ALL latched voices
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         return; // Skip other logic for shift cursor
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId);
            const targetNode = nodeMapRef.current.get(cursor.hoverNodeId || "");

            // Re-center pitch of original voices immediately (reset glide)
            audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     activations.forEach(act => {
                         audioEngine.glideVoice(`node-${nodeId}-${act.mode}`, node.ratio, settingsRef.current.baseFrequency);
                     });
                 }
            });

            if (anchorNode && targetNode && anchorNode.id !== targetNode.id) {
                // Calculate transposition vector in coordinate space
                // Diff: Target - Anchor
                const diffCoords = targetNode.coords.map((c, i) => c - anchorNode.coords[i]);
                const diffOctave = targetNode.octave - anchorNode.octave;

                const newLatches = new Map<string, Map<number, number>>();

                // If Move (Sustain Off), start with empty map. If Copy (Sustain On), start with existing.
                if (isSustainActive) {
                    persistentLatchesRef.current.forEach((v, k) => newLatches.set(k, v));
                }

                // Iterate originals and transpose
                persistentLatchesRef.current.forEach((modes, sourceId) => {
                    const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
                    if (sourceNode) {
                        // Apply Vector
                        const newCoords = sourceNode.coords.map((c, i) => c + (diffCoords[i] || 0));
                        const newOct = sourceNode.octave + diffOctave;
                        const newId = `${newCoords.join(',')}:${newOct}`;

                        // Check if valid node exists or force creating phantom?
                        // For lattice consistency, best to check if it exists in current lattice.
                        if (nodeMapRef.current.has(newId)) {
                            // Merge modes
                            const targetModes = newLatches.get(newId) || new Map<number, number>();
                            modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                            newLatches.set(newId, targetModes);
                        }
                    }
                });

                setPersistentLatches(newLatches);
            }
        } 
        // --- NORMAL LOGIC ---
        else {
            if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React from 'react';
import { AppSettings, XYPos } from '../../types';

interface Props {
    isBendEnabled: boolean;
    latchMode: number;
    isSustainEnabled?: boolean;
    isModulationModeActive?: boolean;
    modulationPathLength?: number;
    isShiftModeActive?: boolean; // NEW
    uiUnlocked: boolean;
    uiScale: number;
    positions: AppSettings['uiPositions'];

    onBend: () => void;
    onSustainToggle?: () => void;
    onOff: () => void;
    onPanic: () => void;
    onModulationToggle?: () => void;
    onModulationUndo?: () => void;
    onModulationReset?: () => void;
    onShiftToggle?: () => void; // NEW
    onDragStart: (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => void;
}

const PerformanceControls: React.FC<Props> = ({
    isBendEnabled, latchMode, isSustainEnabled, isModulationModeActive, modulationPathLength = 0, isShiftModeActive,
    uiUnlocked, uiScale, positions,
    onBend, onSustainToggle, onOff, onPanic, onModulationToggle, onModulationUndo, onModulationReset, onShiftToggle,
    onDragStart
}) => {

    const perfBtnSize = 92 * uiScale;
    const fontSize = 16 * uiScale;

    const draggableStyle = (key: keyof AppSettings['uiPositions']) => ({
        left: positions[key].x,
        top: positions[key].y,
        width: perfBtnSize,
        height: perfBtnSize,
        fontSize: fontSize,
        touchAction: 'none' as React.CSSProperties['touchAction'],
    });

    const handlePress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action?: () => void) => {
        e.stopPropagation();
        if (uiUnlocked) {
            onDragStart(e, key);
        } else {
            if (e.button === 0 && action) action();
        }
    };

    const sustColorClass = latchMode === 1 
        ? (isSustainEnabled 
            ? 'bg-green-600 text-white border-green-300 shadow-[0_0_15px_rgba(34,197,94,0.6)]' 
            : 'bg-green-900/40 text-green-400 border-green-500/50 hover:bg-green-800/60')
        : (isSustainEnabled 
            ? 'bg-blue-600 text-white border-blue-300 shadow-[0_0_15px_rgba(37,99,235,0.6)]' 
            : 'bg-blue-900/40 text-blue-400 border-blue-500/50 hover:bg-blue-800/60');

    // --- Satellite Logic ---
    const showSatellites = modulationPathLength > 1;
    const satelliteSize = perfBtnSize * 0.4;
    const modX = positions.mod.x;
    const modY = positions.mod.y;

    const offsetDistance = perfBtnSize * 0.6;
    const undoX = modX + (perfBtnSize/2) - (satelliteSize/2) - offsetDistance;
    const undoY = modY + (perfBtnSize/2) - (satelliteSize/2) - offsetDistance * 0.8;

    const resetX = modX + (perfBtnSize/2) - (satelliteSize/2) + offsetDistance;
    const resetY = modY + (perfBtnSize/2) - (satelliteSize/2) - offsetDistance * 0.8;

    return (
        <>
            {/* Shift Button (New) */}
            <button 
                className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${isShiftModeActive ? 'bg-orange-600 text-white border-orange-300 shadow-[0_0_15px_rgba(249,115,22,0.6)]' : 'bg-orange-900/40 text-orange-400 border-orange-500/50 hover:bg-orange-800/60'} ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} 
                style={draggableStyle('shift')} 
                onPointerDown={(e) => handlePress(e, 'shift', onShiftToggle)}
                aria-label="Toggle Chord Shift"
                title="Shift Mode: Drag any latched note to transpose entire chord"
            >
                SHIFT
            </button>

            <button 
                className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${isBendEnabled ? 'bg-purple-600 text-white border-purple-300 shadow-[0_0_15px_rgba(168,85,247,0.6)]' : 'bg-purple-900/40 text-purple-400 border-purple-500/50 hover:bg-purple-800/60'} ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} 
                style={draggableStyle('bend')} 
                onPointerDown={(e) => handlePress(e, 'bend', onBend)}
                aria-label="Toggle Pitch Bend"
            >
                BEND
            </button>

            <button 
                className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${sustColorClass} ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} 
                style={draggableStyle('sust')} 
                onPointerDown={(e) => handlePress(e, 'sust', onSustainToggle)} 
                title="Sustain Notes"
                aria-label="Toggle Sustain"
            >
                SUST
            </button>

            <button 
                className={`absolute rounded-full bg-yellow-900/40 border-2 border-yellow-500/50 flex items-center justify-center text-yellow-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-yellow-800/60 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.2)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} 
                style={draggableStyle('off')} 
                onPointerDown={(e) => handlePress(e, 'off', onOff)} 
                aria-label="Stop All Notes"
            >
                OFF
            </button>

            <button 
                className={`absolute rounded-full bg-red-900/40 border-2 border-red-500/50 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-red-800/60 active:bg-red-600 active:text-white transition-all shadow-[0_0_15px_rgba(239,68,68,0.2)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} 
                style={draggableStyle('panic')} 
                onPointerDown={(e) => handlePress(e, 'panic', onPanic)} 
                aria-label="Panic Stop"
            >
                PANIC
            </button>

            {/* Modulation Satellites */}
            {showSatellites && !uiUnlocked && (
                <>
                    <button
                        className="absolute rounded-full flex items-center justify-center bg-cyan-900/80 border border-cyan-400 text-cyan-200 hover:bg-cyan-700 hover:text-white hover:scale-110 hover:shadow-[0_0_10px_cyan] transition-all z-[160] animate-in fade-in zoom-in duration-300"
                        style={{ left: undoX, top: undoY, width: satelliteSize, height: satelliteSize }}
                        onPointerDown={(e) => { e.stopPropagation(); if (onModulationUndo) onModulationUndo(); }}
                        title="Undo Last Pivot"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" style={{ width: '60%', height: '60%' }}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M9 15L3 9m0 0l6-6M3 9h12a6 6 0 010 12h-3" />
                        </svg>
                    </button>

                    <button
                        className="absolute rounded-full flex items-center justify-center bg-red-900/80 border border-red-400 text-red-200 hover:bg-red-700 hover:text-white hover:scale-110 hover:shadow-[0_0_10px_red] transition-all z-[160] animate-in fade-in zoom-in duration-300"
                        style={{ left: resetX, top: resetY, width: satelliteSize, height: satelliteSize }}
                        onPointerDown={(e) => { e.stopPropagation(); if (onModulationReset) onModulationReset(); }}
                        title="Clear Modulation (Reset to Root)"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" style={{ width: '60%', height: '60%' }}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </>
            )}

            {/* Modulation Main Button */}
            <button 
                className={`absolute rounded-full flex flex-col items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg 
                    ${isModulationModeActive 
                        ? 'bg-cyan-600 text-white border-cyan-300 shadow-[0_0_20px_rgba(34,211,238,0.5)]' 
                        : (showSatellites ? 'bg-cyan-900/60 text-cyan-200 border-cyan-500/80 shadow-[0_0_10px_rgba(34,211,238,0.3)]' : 'bg-cyan-900/40 text-cyan-400 border-cyan-500/50 hover:bg-cyan-800/60')
                    } ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} 
                style={draggableStyle('mod')} 
                onPointerDown={(e) => handlePress(e, 'mod', onModulationToggle)}
                title="Modulation Mode (Click Node to Pivot)"
                aria-label="Toggle Modulation Mode"
            >
                <span className="leading-none">MOD</span>
                {showSatellites && (
                    <span className="text-[9px] opacity-80 leading-none mt-0.5 font-mono">{modulationPathLength}</span>
                )}
            </button>
        </>
    );
};

export default PerformanceControls;

import React, { useState, useEffect } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpDivision, ArpeggioStep, PresetState, PlayMode, SynthPreset, UISize } from '../types';
import ArpeggiatorBar from './controls/ArpeggiatorBar';
import InstrumentCluster from './controls/InstrumentCluster';
import MasterControls from './controls/MasterControls';
import PerformanceControls from './controls/PerformanceControls';
import ViewControls from './controls/ViewControls';
import ChordBar from './controls/ChordBar';
import { useDragManager } from '../hooks/useDragManager';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;
  viewZoom: number;
  setViewZoom: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void; 
  onSust?: () => void; 
  onPluck?: () => void; 
  onVoice?: () => void; 
  onKeys?: () => void;
  onPercussion?: () => void; 
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  onBend: () => void;
  isBendEnabled: boolean;
  onSustainToggle?: () => void;
  isSustainEnabled?: boolean;
  onModulationToggle?: () => void;
  isModulationModeActive?: boolean;
  modulationPathLength?: number;
  onModulationUndo?: () => void;
  onModulationReset?: () => void;
  onShiftToggle?: () => void;
  isShiftModeActive?: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  onRemoveChord?: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  uiSizes?: AppSettings['uiSizes'];
  updateSize?: (key: keyof AppSettings['uiSizes'], size: UISize) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
  onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
  recordingFlash?: number;
  onPlayAll?: () => void;
  onStopAll?: () => void;

  maxArpWidth?: number; 
  activeSustainedModes?: number[];
  onClearSustain?: (mode: number) => void;

  isSequencerOpen: boolean;
  onToggleSequencer: () => void;

  presets?: PresetState;
  onPresetChange?: (mode: PlayMode, preset: SynthPreset) => void;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness, viewZoom, setViewZoom,
  onPanic, onOff, onLatch, onSust, onPluck, onVoice, onKeys, onPercussion, latchMode, onBend, isBendEnabled, onSustainToggle, isSustainEnabled, 
  onModulationToggle, isModulationModeActive, modulationPathLength, onModulationUndo, onModulationReset, onShiftToggle, isShiftModeActive,
  onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord, onRemoveChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  uiSizes, updateSize,
  draggingId, setDraggingId, uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate, recordingArpId, currentArpStep, recordingFlash = 0,
  onPlayAll, onStopAll,
  maxArpWidth,
  activeSustainedModes = [],
  onClearSustain,
  isSequencerOpen,
  onToggleSequencer,
  presets,
  onPresetChange
}) => {

  const [isFlashingRed, setIsFlashingRed] = useState(false);

  useEffect(() => {
      if (recordingFlash > 0) {
          setIsFlashingRed(true);
          const t = setTimeout(() => setIsFlashingRed(false), 200);
          return () => clearTimeout(t);
      }
  }, [recordingFlash]);

  const handleDrag = useDragManager(
      uiUnlocked,
      draggingId,
      setDraggingId,
      (id, pos) => updatePosition(id as any, pos),
      uiPositions as any
  );

  const handleResize = (e: React.PointerEvent, key: 'volume' | 'arpeggioBar', axis: 'x' | 'y' | 'xy') => {
      e.stopPropagation();
      e.preventDefault();
      if (!updateSize || !uiSizes) return;

      const el = e.currentTarget as HTMLElement;
      el.setPointerCapture(e.pointerId);

      const startX = e.clientX;
      const startY = e.clientY;

      const initialWidth = uiSizes[key]?.width || (key === 'volume' ? 600 : 760);
      const initialHeight = uiSizes[key]?.height || (key === 'volume' ? 75 : 0); 

      const onMove = (evt: PointerEvent) => {
          const deltaX = (evt.clientX - startX) / uiScale;
          const deltaY = (evt.clientY - startY) / uiScale;

          let newWidth = initialWidth;
          let newHeight = initialHeight;

          if (axis === 'x' || axis === 'xy') {
              const minW = key === 'volume' ? 320 : 300; 
              newWidth = Math.max(minW, initialWidth + deltaX);
          }
          if ((axis === 'y' || axis === 'xy') && key === 'volume') {
              const minH = 60; 
              newHeight = Math.max(minH, initialHeight + deltaY);
          }

          updateSize(key, { width: newWidth, height: newHeight });
      };

      const onUp = () => {
          window.removeEventListener('pointermove', onMove);
          window.removeEventListener('pointerup', onUp);
          window.removeEventListener('pointercancel', onUp);
      };

      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
      window.addEventListener('pointercancel', onUp);
  };

  const arpBaseWidth = uiSizes?.arpeggioBar?.width || 760;
  const userArpWidth = arpBaseWidth * uiScale;
  const effectiveArpWidth = maxArpWidth ? Math.min(userArpWidth, maxArpWidth) : userArpWidth;
  const isConstrained = effectiveArpWidth < (760 * uiScale) * 0.95;

  const resizeHandleStyle = "absolute z-50 bg-yellow-500/50 hover:bg-yellow-400 rounded-sm border border-white/50 shadow-sm transition-colors";

  return (
    <>
      <MasterControls 
          volume={volume} setVolume={setVolume}
          spatialScale={spatialScale} setSpatialScale={setSpatialScale}
          brightness={brightness} setBrightness={setBrightness}
          viewZoom={viewZoom} setViewZoom={setViewZoom}
          uiScale={uiScale}
          uiUnlocked={uiUnlocked}
          position={uiPositions.volume}
          size={uiSizes?.volume || { width: 600, height: 75 }}
          onDragStart={(e) => handleDrag(e, 'volume')}
          onResize={(e, axis) => handleResize(e, 'volume', axis)}
      />

      <div style={{ position: 'absolute', left: 0, top: 0, width: 0, height: 0 }}>
          {uiUnlocked && (
              <div 
                  className={`${resizeHandleStyle} cursor-ew-resize`}
                  style={{ 
                      left: uiPositions.arpeggioBar.x + effectiveArpWidth - 6, 
                      top: uiPositions.arpeggioBar.y, 
                      height: 52 * uiScale, 
                      width: 12,
                      zIndex: 160 
                  }}
                  onPointerDown={(e) => handleResize(e, 'arpeggioBar', 'x')}
              />
          )}
      </div>

      <ArpeggiatorBar 
          arpeggios={arpeggios}
          arpBpm={arpBpm}
          onArpToggle={onArpToggle}
          onArpBpmChange={onArpBpmChange}
          onArpRowConfigChange={onArpRowConfigChange}
          onArpPatternUpdate={onArpPatternUpdate}
          recordingArpId={recordingArpId}
          currentArpStep={currentArpStep}
          onPlayAll={onPlayAll}
          onStopAll={onStopAll}
          isSequencerOpen={isSequencerOpen}
          onToggleSequencer={onToggleSequencer}
          uiScale={uiScale}
          position={uiPositions.arpeggioBar}
          isConstrained={isConstrained}
          width={effectiveArpWidth}
          onDragStart={(e) => handleDrag(e, 'arpeggioBar')}
          isFlashingRed={isFlashingRed}
          uiUnlocked={uiUnlocked}
      />

      <InstrumentCluster 
          latchMode={latchMode}
          onLatch={onLatch}
          onSust={onSust}
          onPluck={onPluck}
          onVoice={onVoice}
          onKeys={onKeys}
          onPercussion={onPercussion}
          activeSustainedModes={activeSustainedModes}
          onClearSustain={onClearSustain}
          presets={presets}
          onPresetChange={onPresetChange}
          uiScale={uiScale}
          position={uiPositions.instruments}
          onDragStart={(e) => handleDrag(e, 'instruments')}
          uiUnlocked={uiUnlocked}
      />

      <PerformanceControls 
          isBendEnabled={isBendEnabled}
          latchMode={latchMode as any}
          isSustainEnabled={isSustainEnabled}
          isModulationModeActive={isModulationModeActive}
          modulationPathLength={modulationPathLength}
          isShiftModeActive={isShiftModeActive}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          positions={uiPositions}
          onBend={onBend}
          onSustainToggle={onSustainToggle}
          onOff={onOff}
          onPanic={onPanic}
          onModulationToggle={onModulationToggle}
          onModulationUndo={onModulationUndo}
          onModulationReset={onModulationReset}
          onShiftToggle={onShiftToggle}
          onDragStart={handleDrag}
      />

      <ViewControls 
          showIncreaseDepthButton={showIncreaseDepthButton}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          positions={uiPositions}
          onCenter={onCenter}
          onIncreaseDepth={onIncreaseDepth}
          onDecreaseDepth={onDecreaseDepth}
          onDragStart={handleDrag}
      />

      <ChordBar 
          savedChords={savedChords}
          activeChordIds={activeChordIds}
          chordShortcutSizeScale={chordShortcutSizeScale}
          uiUnlocked={uiUnlocked}
          uiScale={uiScale}
          position={uiPositions.chords}
          onAddChord={onAddChord}
          toggleChord={toggleChord}
          onRemoveChord={onRemoveChord}
          onDragStart={handleDrag}
      />
    </>
  );
};

export default FloatingControls;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import RecordingControls from './components/RecordingControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, XYPos, UISize, SynthPreset } from './types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from './constants';
import { useAppLayout } from './hooks/useAppLayout';
import { useArpeggiatorLogic } from './hooks/useArpeggiatorLogic';
import { useKeyboardControls } from './hooks/useKeyboardControls';
import { usePerformanceState } from './hooks/usePerformanceState';
import { useAudioSystem } from './hooks/useAudioSystem';

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  // Visual State
  const [viewZoom, setViewZoom] = useState(1.0);

  // UI State
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);
  const [isSequencerOpen, setIsSequencerOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // --- Custom Hooks ---

  // 1. Audio System (State, Sync, Warmup)
  const {
      masterVolume, setMasterVolume,
      spatialScale, setSpatialScale,
      brightness, setBrightness,
      stopAudio
  } = useAudioSystem(settings, presets);

  // 2. Layout Logic
  const { autoScaleFactor, isShortScreen } = useAppLayout(settings, updateSettings);
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  // 3. Performance Logic (Instrument Modes, Sustain, Bend, Modulation)
  const {
      latchMode,
      activeSustainedModes,
      handleDroneSelect,
      handleStringSelect,
      handlePluckedSelect,
      handleVoiceSelect,
      handleKeysSelect,
      handlePercussionSelect,
      handleSustainToggle,
      handleBendToggle,
      handleShiftToggle, // NEW
      handleModulationToggle,
      handleModulationUndo,
      handleModulationReset,
      handleSustainStatusChange
  } = usePerformanceState(settings, updateSettings);

  // 4. Arpeggiator Logic
  const {
      recordingArpId,
      setRecordingArpId,
      currentArpStep,
      recordingFlash,
      handleArpToggle,
      handleArpRecordNote,
      handleArpPatternUpdate,
      handleArpBpmChange,
      handleArpRowConfigChange,
      handlePlayAll,
      handleStopAll,
      stopArpAndRecording
  } = useArpeggiatorLogic(settings, updateSettings, diamondRef, latchMode);

  // --- Effects ---

  // Apply UI Scale CSS
  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  // --- Handlers ---

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    stopAudio(); 
    stopArpAndRecording();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setRecordingArpId(null);
  };

  const handleClearSustain = (mode: number) => {
      diamondRef.current?.clearLatches(mode);
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedData = diamondRef.current.getLatchedNodes();
          if (latchedData.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const uniqueTimestamp = Date.now();
              const soundConfigs: Partial<Record<import('./types').PlayMode, SynthPreset>> = {};
              const usedModes = new Set<import('./types').PlayMode>();

              const simplifiedNodes = latchedData.map(({ node, mode }) => {
                  let modeStr: import('./types').PlayMode = 'normal';
                  if (mode === 1) modeStr = 'latch';
                  else if (mode === 2) modeStr = 'normal';
                  else if (mode === 3) modeStr = 'strum';
                  else if (mode === 4) modeStr = 'brass'; 
                  else if (mode === 5) modeStr = 'keys';
                  else if (mode === 6) modeStr = 'percussion';
                  usedModes.add(modeStr);

                  return { id: node.id, n: node.n, d: node.d, voiceMode: modeStr };
              });

              usedModes.forEach(m => {
                  soundConfigs[m] = JSON.parse(JSON.stringify(presets[m]));
                  if (soundConfigs[m]) {
                      soundConfigs[m]!.id = `chord-${newChords[slotIndex].id}-${m}-${uniqueTimestamp}`;
                  }
              });

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 },
                  soundConfigs: soundConfigs,
                  soundConfig: undefined 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      if (settings.isSustainEnabled) {
          setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
      } else {
          setActiveChordIds(prev => prev.includes(id) ? [] : [id]);
      }
  };

  const handleRemoveChord = (id: string) => {
      const newChords = settings.savedChords.map(c => {
          if (c.id === id) {
              return { ...c, nodes: [], visible: false, soundConfig: undefined, soundConfigs: undefined };
          }
          return c;
      });
      updateSettings(prev => ({ ...prev, savedChords: newChords }));

      if (activeChordIds.includes(id)) {
          setActiveChordIds(prev => prev.filter(cid => cid !== id));
      }
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  const handleUiSizeUpdate = (key: keyof AppSettings['uiSizes'], size: UISize) => {
      updateSettings(prev => ({ ...prev, uiSizes: { ...prev.uiSizes, [key]: size } }));
  };

  useKeyboardControls({
      settings, latchMode,
      isSettingsOpen, setIsSettingsOpen,
      isSynthOpen, setIsSynthOpen,
      setMasterVolume, setSpatialScale, setIsSequencerOpen,
      handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
      handleSustainToggle, handleBendToggle, handlePanic, handleCenter, handleOff,
      handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
      handlePlayAll, handleStopAll
  });

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const top = parseInt(computed.paddingTop) || 0;
      document.body.removeChild(div);
      return { top, left: 0, right: 0, bottom: 0 };
  };
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  const arpX = settings.uiPositions.arpeggioBar.x;
  const volX = settings.uiPositions.volume.x;
  const gap = 20 * effectiveScale;
  const availableArpWidth = Math.max(0, volX - arpX - gap);
  const showArpBar = availableArpWidth > 250 * effectiveScale;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        isCurrentSustainEnabled={settings.isSustainEnabled} 
        globalScale={effectiveScale}
        viewZoom={viewZoom}
        onNodeTrigger={handleArpRecordNote}
        onSustainStatusChange={handleSustainStatusChange}
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}
        viewZoom={viewZoom} setViewZoom={setViewZoom}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleDroneSelect} 
        onSust={handleStringSelect} 
        onPluck={handlePluckedSelect}
        onVoice={handleVoiceSelect}
        onKeys={handleKeysSelect}
        onPercussion={handlePercussionSelect}
        latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onSustainToggle={handleSustainToggle} isSustainEnabled={settings.isSustainEnabled}
        onModulationToggle={handleModulationToggle} isModulationModeActive={settings.isModulationModeActive}
        modulationPathLength={settings.modulationPath.length}
        onModulationUndo={handleModulationUndo}
        onModulationReset={handleModulationReset}
        onShiftToggle={handleShiftToggle} isShiftModeActive={settings.isShiftModeActive}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        onRemoveChord={handleRemoveChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        uiSizes={settings.uiSizes} updateSize={handleUiSizeUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpRowConfigChange={handleArpRowConfigChange}
        onArpPatternUpdate={handleArpPatternUpdate}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
        recordingFlash={recordingFlash}
        onPlayAll={handlePlayAll}
        onStopAll={handleStopAll}

        activeSustainedModes={activeSustainedModes}
        maxArpWidth={showArpBar ? availableArpWidth : 0}
        onClearSustain={handleClearSustain}

        isSequencerOpen={isSequencerOpen}
        onToggleSequencer={() => setIsSequencerOpen(p => !p)}

        presets={presets}
        onPresetChange={setPreset}
      />

      <LimitLayerControls 
        settings={settings} 
        updateSettings={updateSettings} 
        draggingId={draggingId} 
        setDraggingId={setDraggingId} 
        uiScale={effectiveScale}
        isShortScreen={isShortScreen}
      />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />

      <RecordingControls />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; // Track if this cursor is controlling a chord shift
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  // This happens when modulating away from a center but keeping notes latched.
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              // Try to reconstruct the node data from ID
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      // Also check active cursors if they are holding a node that disappeared
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          // Determine if we should show cursor glow
          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate predicted "Ghost" nodes for Shift Mode
  const shiftGhostNodes = useMemo(() => {
      const ghosts = new Set<string>();
      if (!settings.isShiftModeActive) return ghosts;

      // Find an active shift anchor
      let anchorCursor: ActiveCursor | null = null;
      for (const c of activeCursors.values()) {
          if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
              anchorCursor = c;
              break;
          }
      }

      if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
          const anchorNode = nodeMap.get(anchorCursor.originNodeId) || phantomNodes.get(anchorCursor.originNodeId);
          const targetNode = nodeMap.get(anchorCursor.hoverNodeId) || phantomNodes.get(anchorCursor.hoverNodeId);

          if (anchorNode && targetNode && anchorNode.id !== targetNode.id) {
              // Calculate vector
              const diffCoords = targetNode.coords.map((c, i) => c - anchorNode.coords[i]);
              const diffOctave = targetNode.octave - anchorNode.octave;

              // Apply to all latched nodes
              visualLatchedNodes.forEach((_, sourceId) => {
                  const sourceNode = nodeMap.get(sourceId) || phantomNodes.get(sourceId);
                  if (sourceNode) {
                      const newCoords = sourceNode.coords.map((c, i) => c + (diffCoords[i] || 0));
                      const newOct = sourceNode.octave + diffOctave;
                      const newId = `${newCoords.join(',')}:${newOct}`;

                      // Only show ghost if it lands on a valid node in the current view
                      if (nodeMap.has(newId)) {
                          ghosts.add(newId);
                      }
                  }
              });
          }
      }
      return ghosts;
  }, [settings.isShiftModeActive, activeCursors, visualLatchedNodes, nodeMap, phantomNodes]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const shiftGhostNodesRef = useRef(shiftGhostNodes); // NEW
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { shiftGhostNodesRef.current = shiftGhostNodes; }, [shiftGhostNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        if (settings.isModulationModeActive) {
            const newOrigin: GenerationOrigin = {
                coords: hitNode.coords,
                octave: hitNode.octave
            };

            const newPath = [...settings.modulationPath, newOrigin];

            const currentOrigin = settings.modulationPath[settings.modulationPath.length - 1];
            const isSame = currentOrigin.coords.every((v, i) => v === hitNode.coords[i]) && currentOrigin.octave === hitNode.octave;

            if (!isSame) {
                updateSettings({ 
                    modulationPath: newPath,
                    isModulationModeActive: false
                });
            }
            return; 
        }

        // --- SHIFT LOGIC (Initiate) ---
        const isShiftMode = settings.isShiftModeActive;
        const currentLatches = persistentLatchesRef.current;
        const isClickedLatched = currentLatches.has(hitNode.id);

        if (isShiftMode && isClickedLatched) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: true // Mark as anchor
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            return; // Don't trigger sound or normal latch logic
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                 const next = new Map(prev);
                 const nodeModes = next.get(hitNode.id) || new Map<number, number>();

                 if (nodeModes.has(latchMode)) {
                     nodeModes.delete(latchMode);
                 } else {
                     nodeModes.set(latchMode, Date.now());
                 }

                 if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                 else next.delete(hitNode.id);
                 return next;
             });
        }

        if ((isBendEnabled || !isSustainActive) && !isShiftMode) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ALL latched voices
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId);
            const targetNode = nodeMapRef.current.get(cursor.hoverNodeId || "");

            // Re-center pitch of original voices immediately (reset glide)
            audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     activations.forEach(act => {
                         audioEngine.glideVoice(`node-${nodeId}-${act.mode}`, node.ratio, settingsRef.current.baseFrequency);
                     });
                 }
            });

            if (anchorNode && targetNode && anchorNode.id !== targetNode.id) {
                // Calculate transposition vector in coordinate space
                // Diff: Target - Anchor
                const diffCoords = targetNode.coords.map((c, i) => c - anchorNode.coords[i]);
                const diffOctave = targetNode.octave - anchorNode.octave;

                const newLatches = new Map<string, Map<number, number>>();

                // If Move (Sustain Off), start with empty map. If Copy (Sustain On), start with existing.
                if (isSustainActive) {
                    persistentLatchesRef.current.forEach((v, k) => newLatches.set(k, v));
                }

                // Iterate originals and transpose
                persistentLatchesRef.current.forEach((modes, sourceId) => {
                    const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
                    if (sourceNode) {
                        // Apply Vector
                        const newCoords = sourceNode.coords.map((c, i) => c + (diffCoords[i] || 0));
                        const newOct = sourceNode.octave + diffOctave;
                        const newId = `${newCoords.join(',')}:${newOct}`;

                        // Check if valid node exists or force creating phantom?
                        // For lattice consistency, best to check if it exists in current lattice.
                        if (nodeMapRef.current.has(newId)) {
                            // Merge modes
                            const targetModes = newLatches.get(newId) || new Map<number, number>();
                            modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                            newLatches.set(newId, targetModes);
                        }
                    }
                });

                setPersistentLatches(newLatches);
            }
        } 
        // --- NORMAL LOGIC ---
        else {
            if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; 
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
    phantomNodes?: Map<string, LatticeNode>; 
}

const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, 
    3: 1, 
    2: 2, 
    4: 3, 
    5: 4, 
    'arp': 5, 
    1: 6  
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(staticCanvas, state);
        this.renderDynamic(bgCanvas, activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return { bg: '#f8fafc', line: '#94a3b8', lineDim: 'rgba(148, 163, 184, 0.2)', nodeText: '#334155', nodeStroke: '#334155', nodeFill: () => '#ffffff', shadow: 'rgba(0,0,0,0.1)' };
            case 'blueprint':
                return { bg: '#1e3a8a', line: 'rgba(147, 197, 253, 0.4)', lineDim: 'rgba(147, 197, 253, 0.1)', nodeText: '#dbeafe', nodeStroke: '#93c5fd', nodeFill: () => '#172554', shadow: 'rgba(0,0,0,0.3)' };
            case 'cyber':
                return { bg: '#000000', line: '#333333', lineDim: '#111111', nodeText: '#ffffff', nodeStroke: '#444444', nodeFill: () => '#000000', shadow: '#00ff00' };
            case 'default':
            default:
                return { bg: 'transparent', line: '#666', lineDim: 'rgba(255,255,255,0.1)', nodeText: '#ffffff', nodeStroke: 'transparent', nodeFill: (limit, map) => map[limit] || '#666', shadow: 'black' };
        }
    }

    private renderStatic(canvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            linesLen: data.lines.length,
            path: settings.modulationPath,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (canvas.width !== view.w * dpr || canvas.height !== view.h * dpr) {
            canvas.width = view.w * dpr;
            canvas.height = view.h * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Nodes (Lines removed per request)
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const radius = Math.max(0, baseRadius * topVis.size);

            if (node.isGhost) {
                // Ghost Node Trace: Outline only, no fill, very faint
                ctx.globalAlpha = 0.15;
                ctx.strokeStyle = '#64748b';
                ctx.lineWidth = 1 * effectiveScale;
                ctx.beginPath();
                if (isDiamond) {
                    ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
                } else {
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                }
                ctx.closePath();
                ctx.stroke();
                ctx.globalAlpha = 1.0;
                continue; 
            }

            ctx.globalAlpha = 1.0 * topVis.opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad; ctx.fill();
            }

            if (settings.buttonSizeScale * topVis.size > 0.4) {
                ctx.fillStyle = skin.nodeText; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * settings.buttonSizeScale * topVis.size)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath(); ctx.moveTo(x - (radius * 0.4), y); ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale; ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,0.8)`;
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(bgCanvas: HTMLCanvasElement, activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, phantomNodes, activeCursors,
            effectiveScale, centerOffset, view, time 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (bgCanvas.width !== view.w * dpr || bgCanvas.height !== view.h * dpr) {
            bgCanvas.width = view.w * dpr; bgCanvas.height = view.h * dpr;
            activeCanvas.width = view.w * dpr; activeCanvas.height = view.h * dpr;
        }

        bgCtx.setTransform(1, 0, 0, 1, 0, 0); activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height); activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        bgCtx.scale(dpr, dpr); activeCtx.scale(dpr, dpr);
        bgCtx.translate(-view.x, -view.y); activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad; const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad; const cullBottom = view.y + view.h + cullPad;

        bgCtx.lineCap = 'round'; activeCtx.lineCap = 'round';

        // --- DRAW MODULATION PATH ---
        if (settings.modulationPath.length > 1) {
            bgCtx.beginPath();
            let started = false;

            settings.modulationPath.forEach((p) => {
                const originId = `${p.coords.join(',')}:${p.octave}`;
                const node = this.cachedNodeMap.get(originId);

                if (node) {
                    const sx = node.x * spacing + centerOffset;
                    const sy = node.y * spacing + centerOffset;
                    if (!started) {
                        bgCtx.moveTo(sx, sy);
                        started = true;
                    } else {
                        bgCtx.lineTo(sx, sy);
                    }
                }
            });

            if (started) {
                bgCtx.lineWidth = 2 * effectiveScale;
                bgCtx.strokeStyle = '#22d3ee'; // Cyan
                bgCtx.setLineDash([10 * effectiveScale, 10 * effectiveScale]);
                bgCtx.lineDashOffset = -time * 0.05;
                bgCtx.stroke();
                bgCtx.setLineDash([]);

                // Draw dots at pivots
                settings.modulationPath.forEach(p => {
                    const originId = `${p.coords.join(',')}:${p.octave}`;
                    const node = this.cachedNodeMap.get(originId);
                    if (node) {
                        const sx = node.x * spacing + centerOffset;
                        const sy = node.y * spacing + centerOffset;
                        bgCtx.beginPath();
                        bgCtx.arc(sx, sy, 4 * effectiveScale, 0, Math.PI * 2);
                        bgCtx.fillStyle = '#22d3ee';
                        bgCtx.fill();
                    }
                });
            }
        }

        // --- RENDER GHOSTS (SHIFT MODE) ---
        if (settings.isShiftModeActive) {
            let anchorCursor: any = null;
            for (const c of activeCursors.values()) {
                if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
                    anchorCursor = c;
                    break;
                }
            }

            if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
                const anchorNode = this.cachedNodeMap.get(anchorCursor.originNodeId) || phantomNodes?.get(anchorCursor.originNodeId);
                const targetNode = this.cachedNodeMap.get(anchorCursor.hoverNodeId) || phantomNodes?.get(anchorCursor.hoverNodeId);

                if (anchorNode && targetNode && anchorNode.id !== targetNode.id) {
                    const diffCoords = targetNode.coords.map((c, i) => c - anchorNode.coords[i]);
                    const diffOctave = targetNode.octave - anchorNode.octave;

                    visualLatchedNodes.forEach((_, sourceId) => {
                        const sourceNode = this.cachedNodeMap.get(sourceId) || phantomNodes?.get(sourceId);
                        if (sourceNode) {
                            const newCoords = sourceNode.coords.map((c, i) => c + (diffCoords[i] || 0));
                            const newOct = sourceNode.octave + diffOctave;
                            const newId = `${newCoords.join(',')}:${newOct}`;
                            const ghostNode = this.cachedNodeMap.get(newId);

                            if (ghostNode) {
                                const gx = ghostNode.x * spacing + centerOffset;
                                const gy = ghostNode.y * spacing + centerOffset;
                                if (gx < cullLeft || gx > cullRight || gy < cullTop || gy > cullBottom) return;

                                const gRadius = Math.max(0, baseRadius * settings.latchedZoomScale);
                                activeCtx.beginPath();
                                if (isDiamond) {
                                    activeCtx.moveTo(gx, gy - gRadius); activeCtx.lineTo(gx + gRadius, gy); activeCtx.lineTo(gx, gy + gRadius); activeCtx.lineTo(gx - gRadius, gy);
                                } else {
                                    activeCtx.arc(gx, gy, gRadius, 0, Math.PI * 2);
                                }
                                activeCtx.closePath();
                                activeCtx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Cyan tint
                                activeCtx.fill();
                                activeCtx.strokeStyle = '#22d3ee';
                                activeCtx.lineWidth = 2 * effectiveScale;
                                activeCtx.setLineDash([4 * effectiveScale, 4 * effectiveScale]);
                                activeCtx.stroke();
                                activeCtx.setLineDash([]);
                            }
                        }
                    });
                }
            }
        }

        // 1. Draw Brightened Lines (Neighbor Hints)
        if (brightenedLines.length > 0) {
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset; const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset; const y2 = line.y2 * spacing + centerOffset;
                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = 1 * effectiveScale;
                activeCtx.strokeStyle = settings.colors[line.limit] || '#666';
                activeCtx.globalAlpha = 0.8; activeCtx.stroke();
            }
        }

        // 2. Draw Active Lines (Strong connection)
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset; const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset; const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = 4 * effectiveScale;
            activeCtx.strokeStyle = settings.colors[line.limit] || '#666';
            activeCtx.globalAlpha = 1.0; activeCtx.stroke();
        }

        // 3. Draw Active Nodes (Normal & Phantom)
        for (const [id, activations] of visualLatchedNodes.entries()) {
             // Check both main grid and phantom fallback
             const node = this.cachedNodeMap.get(id) || phantomNodes?.get(id);
             if (!node) continue;

             const isPhantom = !!(phantomNodes?.has(id));

             const x = node.x * spacing + centerOffset; const y = node.y * spacing + centerOffset;
             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const radius = Math.max(0, baseRadius * vis.size * settings.latchedZoomScale);

             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius); activeCtx.lineTo(x + radius, y); activeCtx.lineTo(x, y + radius); activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isFlatSkin) {
                 activeCtx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
                 grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
                 activeCtx.fillStyle = grad;
             }

             // Phantom Visual Style: Reduced Opacity or Dashed Outline
             if (isPhantom) {
                 activeCtx.globalAlpha = 0.5; // "Ghost" look
                 activeCtx.fill();
                 activeCtx.globalAlpha = 1.0;

                 // Draw dashed outline for phantom
                 activeCtx.setLineDash([4 * effectiveScale, 4 * effectiveScale]);
                 activeCtx.strokeStyle = '#fff';
                 activeCtx.lineWidth = 2 * effectiveScale;
                 activeCtx.stroke();
                 activeCtx.setLineDash([]);
             } else {
                 activeCtx.fill();
             }

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));
             const sortedModes = Array.from(uniqueModes).sort((a, b) => (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99));

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';
                 const currentRadius = radius + (2 * effectiveScale) + (index * 6 * effectiveScale);
                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius); activeCtx.lineTo(x + currentRadius, y); activeCtx.lineTo(x, y + currentRadius); activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();
                 activeCtx.strokeStyle = color; activeCtx.lineWidth = 4 * effectiveScale;
                 if (isPhantom) activeCtx.setLineDash([3 * effectiveScale, 3 * effectiveScale]);
                 activeCtx.stroke();
                 activeCtx.setLineDash([]);
             });

             // RE-DRAW TEXT on top of active node
             if (settings.buttonSizeScale * vis.size > 0.4) {
                activeCtx.fillStyle = 'white'; 
                activeCtx.shadowColor = 'black';
                activeCtx.shadowBlur = 4;
                activeCtx.textAlign = 'center'; activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * settings.buttonSizeScale * vis.size * settings.latchedZoomScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath(); activeCtx.moveTo(x - (radius * 0.4), y); activeCtx.lineTo(x + (radius * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale; 
                    activeCtx.strokeStyle = 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
                activeCtx.shadowBlur = 0; 
            }
        }
    }
}

import React, { useEffect } from 'react';
import { AppSettings } from '../types';

interface Props {
    settings: AppSettings;
    latchMode: number;

    isSettingsOpen: boolean;
    setIsSettingsOpen: React.Dispatch<React.SetStateAction<boolean>>;

    isSynthOpen: boolean;
    setIsSynthOpen: React.Dispatch<React.SetStateAction<boolean>>;

    setMasterVolume: React.Dispatch<React.SetStateAction<number>>;
    setSpatialScale: React.Dispatch<React.SetStateAction<number>>;
    setIsSequencerOpen: React.Dispatch<React.SetStateAction<boolean>>;

    handleDroneSelect: () => void;
    handleStringSelect: () => void;
    handlePluckedSelect: () => void;
    handleVoiceSelect: () => void;
    handleKeysSelect?: () => void;
    handlePercussionSelect?: () => void; 
    handleSustainToggle: () => void;
    handleBendToggle: () => void;
    handleShiftToggle?: () => void; // NEW
    handlePanic: () => void;
    handleCenter: () => void;
    handleOff: () => void;
    handleAddChord: () => void;
    handleIncreaseDepth: () => void;
    handleDecreaseDepth: () => void;
    handleArpBpmChange: (bpm: number) => void;
    handlePlayAll: () => void;
    handleStopAll: () => void;
}

export const useKeyboardControls = ({
    settings, latchMode, isSettingsOpen, setIsSettingsOpen, isSynthOpen, setIsSynthOpen,
    setMasterVolume, setSpatialScale, setIsSequencerOpen,
    handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
    handleSustainToggle, handleBendToggle, handleShiftToggle, handlePanic, handleCenter, handleOff,
    handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
    handlePlayAll, handleStopAll
}: Props) => {

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
                setIsSettingsOpen(false); 
                setIsSynthOpen(false); 
                return;
            }

            const target = e.target as HTMLElement;
            if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
            if (!settings.enableKeyboardShortcuts) return;

            const key = e.key.toLowerCase();
            const map = settings.keyMappings;

            // Prevent default scrolling/browser actions for specific mapped keys
            if ([map.latch, map.volumeUp, map.volumeDown, map.spatialScaleUp, map.spatialScaleDown].map(k => k.toLowerCase()).includes(key)) {
                e.preventDefault();
            }

            if (key === map.latch.toLowerCase()) { if (latchMode === 1) handleStringSelect(); else handleDroneSelect(); }
            else if (key === map.modeDrone.toLowerCase()) handleDroneSelect();
            else if (key === map.modeStrings.toLowerCase()) handleStringSelect();
            else if (key === map.modePlucked.toLowerCase()) handlePluckedSelect();
            else if (key === map.modeBrass.toLowerCase()) handleVoiceSelect(); 
            else if (key === (map.modeKeys || '5').toLowerCase() && handleKeysSelect) handleKeysSelect(); 
            else if (key === (map.modePercussion || '6').toLowerCase() && handlePercussionSelect) handlePercussionSelect();
            else if (key === map.sustain.toLowerCase()) handleSustainToggle();
            else if (key === map.bend.toLowerCase()) handleBendToggle();
            else if (key === (map.shift || 'shift').toLowerCase() && handleShiftToggle) handleShiftToggle(); // NEW
            else if (key === map.panic.toLowerCase()) handlePanic();
            else if (key === map.center.toLowerCase()) handleCenter();
            else if (key === map.settings.toLowerCase()) { setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSettingsOpen(false); }
            else if (key === map.synth.toLowerCase()) { setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); }
            else if (key === map.off.toLowerCase()) handleOff();
            else if (key === map.addChord.toLowerCase()) handleAddChord();
            else if (key === map.increaseDepth.toLowerCase()) handleIncreaseDepth();
            else if (key === map.decreaseDepth.toLowerCase()) handleDecreaseDepth();
            else if (key === map.volumeUp.toLowerCase()) setMasterVolume(v => Math.min(1.0, v + 0.05));
            else if (key === map.volumeDown.toLowerCase()) setMasterVolume(v => Math.max(0.0, v - 0.05));
            else if (key === map.spatialScaleUp.toLowerCase()) setSpatialScale(s => Math.min(2.0, s + 0.05));
            else if (key === map.spatialScaleDown.toLowerCase()) setSpatialScale(s => Math.max(0.0, s - 0.05));
            else if (key === map.bpmUp.toLowerCase()) handleArpBpmChange(settings.arpBpm + 1);
            else if (key === map.bpmDown.toLowerCase()) handleArpBpmChange(settings.arpBpm - 1);
            else if (key === map.toggleSequencer.toLowerCase()) setIsSequencerOpen(prev => !prev);
            else if (key === map.playAllArps.toLowerCase()) handlePlayAll();
            else if (key === map.stopAllArps.toLowerCase()) handleStopAll();
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [
        settings.enableKeyboardShortcuts, 
        settings.keyMappings, 
        settings.arpBpm,
        latchMode, 
        isSettingsOpen, 
        isSynthOpen,
        handleDroneSelect, handleStringSelect, handlePluckedSelect, handleVoiceSelect, handleKeysSelect, handlePercussionSelect,
        handleSustainToggle, handleBendToggle, handleShiftToggle, handlePanic, handleCenter, handleOff,
        handleAddChord, handleIncreaseDepth, handleDecreaseDepth, handleArpBpmChange,
        handlePlayAll, handleStopAll, setIsSettingsOpen, setIsSynthOpen, setMasterVolume, setSpatialScale, setIsSequencerOpen
    ]);
};

import { LatticeNode, LatticeLine, AppSettings, ButtonShape } from '../types';
import { MODE_COLORS } from '../constants';

interface NodeActivation {
    mode: number | string;
    timestamp: number;
    presetId: string;
}

interface ViewPort {
    x: number;
    y: number;
    w: number;
    h: number;
}

export interface RenderState {
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    settings: AppSettings;
    visualLatchedNodes: Map<string, NodeActivation[]>;
    activeLines: LatticeLine[];
    brightenedLines: LatticeLine[];
    harmonicNeighbors: Map<string, number>; 
    activeCursors: Map<number, any>; 
    cursorPositions: Map<number, {x: number, y: number}>;
    nodeTriggerHistory: Map<string, number>;
    globalBend: number;
    effectiveScale: number;
    centerOffset: number; 
    view: ViewPort;
    time: number;
    latchMode: number;
    phantomNodes?: Map<string, LatticeNode>; 
    shiftGhostNodes?: Map<string, LatticeNode>; // Changed from internal Set logic to explicit Map of Nodes
}

const MODE_PRIORITY: Record<string | number, number> = {
    0: 0, 
    3: 1, 
    2: 2, 
    4: 3, 
    5: 4, 
    'arp': 5, 
    1: 6  
};

interface SkinColors {
    bg: string;
    line: string;
    lineDim: string;
    nodeText: string;
    nodeStroke: string;
    nodeFill: (limit: number, colorMap: Record<number, string>) => string | CanvasGradient;
    shadow: string;
}

export class LatticeRenderer {
    private prevStaticDeps: string = "";
    private cachedDataNodes: LatticeNode[] | null = null;
    private cachedNodeMap: Map<string, LatticeNode> = new Map();

    render(
        bgCanvas: HTMLCanvasElement,
        staticCanvas: HTMLCanvasElement,
        activeCanvas: HTMLCanvasElement,
        state: RenderState
    ) {
        this.renderStatic(staticCanvas, state);
        this.renderDynamic(bgCanvas, activeCanvas, state);
    }

    private getSkinConfig(skin: string, ctx: CanvasRenderingContext2D): SkinColors {
        switch (skin) {
            case 'paper':
                return { bg: '#f8fafc', line: '#94a3b8', lineDim: 'rgba(148, 163, 184, 0.2)', nodeText: '#334155', nodeStroke: '#334155', nodeFill: () => '#ffffff', shadow: 'rgba(0,0,0,0.1)' };
            case 'blueprint':
                return { bg: '#1e3a8a', line: 'rgba(147, 197, 253, 0.4)', lineDim: 'rgba(147, 197, 253, 0.1)', nodeText: '#dbeafe', nodeStroke: '#93c5fd', nodeFill: () => '#172554', shadow: 'rgba(0,0,0,0.3)' };
            case 'cyber':
                return { bg: '#000000', line: '#333333', lineDim: '#111111', nodeText: '#ffffff', nodeStroke: '#444444', nodeFill: () => '#000000', shadow: '#00ff00' };
            case 'default':
            default:
                return { bg: 'transparent', line: '#666', lineDim: 'rgba(255,255,255,0.1)', nodeText: '#ffffff', nodeStroke: 'transparent', nodeFill: (limit, map) => map[limit] || '#666', shadow: 'black' };
        }
    }

    private renderStatic(canvas: HTMLCanvasElement, state: RenderState) {
        const { data, settings, effectiveScale, centerOffset, view } = state;

        const deps = JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            skin: settings.activeSkin,
            size: settings.buttonSizeScale,
            spacing: settings.buttonSpacingScale,
            colors: settings.colors,
            visuals: settings.limitVisuals,
            shape: settings.buttonShape,
            textScale: settings.nodeTextSizeScale,
            fractionBar: settings.showFractionBar,
            scale: effectiveScale,
            nodesLen: data.nodes.length,
            linesLen: data.lines.length,
            path: settings.modulationPath,
            vx: view.x, vy: view.y, vw: view.w, vh: view.h 
        });

        if (deps === this.prevStaticDeps) return;
        this.prevStaticDeps = deps;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (canvas.width !== view.w * dpr || canvas.height !== view.h * dpr) {
            canvas.width = view.w * dpr;
            canvas.height = view.h * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);
        ctx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
        const skin = this.getSkinConfig(settings.activeSkin, ctx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad;
        const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad;
        const cullBottom = view.y + view.h + cullPad;

        // Draw Nodes (Lines removed per request)
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const radius = Math.max(0, baseRadius * topVis.size);

            if (node.isGhost) {
                // Ghost Node Trace: Outline only, no fill, very faint
                ctx.globalAlpha = 0.15;
                ctx.strokeStyle = '#64748b';
                ctx.lineWidth = 1 * effectiveScale;
                ctx.beginPath();
                if (isDiamond) {
                    ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
                } else {
                    ctx.arc(x, y, radius, 0, Math.PI * 2);
                }
                ctx.closePath();
                ctx.stroke();
                ctx.globalAlpha = 1.0;
                continue; 
            }

            ctx.globalAlpha = 1.0 * topVis.opacity;
            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius); ctx.lineTo(x + radius, y); ctx.lineTo(x, y + radius); ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            if (isFlatSkin) {
                ctx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
                ctx.fill();
                ctx.lineWidth = 2 * effectiveScale;
                ctx.strokeStyle = skin.nodeStroke;
                ctx.stroke();
            } else {
                const cTop = settings.colors[node.limitTop] || '#666';
                const cBottom = settings.colors[node.limitBottom] || '#666';
                const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
                grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
                ctx.fillStyle = grad; ctx.fill();
            }

            if (settings.buttonSizeScale * topVis.size > 0.4) {
                ctx.fillStyle = skin.nodeText; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * settings.buttonSizeScale * topVis.size)) * settings.nodeTextSizeScale * effectiveScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    ctx.beginPath(); ctx.moveTo(x - (radius * 0.4), y); ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1 * effectiveScale; ctx.strokeStyle = isFlatSkin ? 'rgba(0,0,0,0.2)' : `rgba(255,255,255,0.8)`;
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
            }
        }
    }

    private renderDynamic(bgCanvas: HTMLCanvasElement, activeCanvas: HTMLCanvasElement, state: RenderState) {
        const { 
            data, settings, visualLatchedNodes, activeLines, brightenedLines, phantomNodes, shiftGhostNodes,
            effectiveScale, centerOffset, view, time 
        } = state;

        if (this.cachedDataNodes !== data.nodes) {
            this.cachedNodeMap = new Map(data.nodes.map(n => [n.id, n]));
            this.cachedDataNodes = data.nodes;
        }

        const bgCtx = bgCanvas.getContext('2d', { alpha: true });
        const activeCtx = activeCanvas.getContext('2d', { alpha: true });
        if (!bgCtx || !activeCtx) return;

        const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
        const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

        if (bgCanvas.width !== view.w * dpr || bgCanvas.height !== view.h * dpr) {
            bgCanvas.width = view.w * dpr; bgCanvas.height = view.h * dpr;
            activeCanvas.width = view.w * dpr; activeCanvas.height = view.h * dpr;
        }

        bgCtx.setTransform(1, 0, 0, 1, 0, 0); activeCtx.setTransform(1, 0, 0, 1, 0, 0);
        bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height); activeCtx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);
        bgCtx.scale(dpr, dpr); activeCtx.scale(dpr, dpr);
        bgCtx.translate(-view.x, -view.y); activeCtx.translate(-view.x, -view.y);

        const spacing = settings.buttonSpacingScale * effectiveScale;
        const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        const skin = this.getSkinConfig(settings.activeSkin, activeCtx);
        const isFlatSkin = settings.activeSkin !== 'default';

        const cullPad = 200;
        const cullLeft = view.x - cullPad; const cullRight = view.x + view.w + cullPad;
        const cullTop = view.y - cullPad; const cullBottom = view.y + view.h + cullPad;

        bgCtx.lineCap = 'round'; activeCtx.lineCap = 'round';

        // --- DRAW MODULATION PATH ---
        if (settings.modulationPath.length > 1) {
            bgCtx.beginPath();
            let started = false;

            settings.modulationPath.forEach((p) => {
                const originId = `${p.coords.join(',')}:${p.octave}`;
                const node = this.cachedNodeMap.get(originId);

                if (node) {
                    const sx = node.x * spacing + centerOffset;
                    const sy = node.y * spacing + centerOffset;
                    if (!started) {
                        bgCtx.moveTo(sx, sy);
                        started = true;
                    } else {
                        bgCtx.lineTo(sx, sy);
                    }
                }
            });

            if (started) {
                bgCtx.lineWidth = 2 * effectiveScale;
                bgCtx.strokeStyle = '#22d3ee'; // Cyan
                bgCtx.setLineDash([10 * effectiveScale, 10 * effectiveScale]);
                bgCtx.lineDashOffset = -time * 0.05;
                bgCtx.stroke();
                bgCtx.setLineDash([]);

                // Draw dots at pivots
                settings.modulationPath.forEach(p => {
                    const originId = `${p.coords.join(',')}:${p.octave}`;
                    const node = this.cachedNodeMap.get(originId);
                    if (node) {
                        const sx = node.x * spacing + centerOffset;
                        const sy = node.y * spacing + centerOffset;
                        bgCtx.beginPath();
                        bgCtx.arc(sx, sy, 4 * effectiveScale, 0, Math.PI * 2);
                        bgCtx.fillStyle = '#22d3ee';
                        bgCtx.fill();
                    }
                });
            }
        }

        // --- RENDER GHOSTS (SHIFT MODE) ---
        if (shiftGhostNodes && shiftGhostNodes.size > 0) {
            shiftGhostNodes.forEach((ghostNode) => {
                const gx = ghostNode.x * spacing + centerOffset;
                const gy = ghostNode.y * spacing + centerOffset;
                if (gx < cullLeft || gx > cullRight || gy < cullTop || gy > cullBottom) return;

                const gRadius = Math.max(0, baseRadius * settings.latchedZoomScale);
                activeCtx.beginPath();
                if (isDiamond) {
                    activeCtx.moveTo(gx, gy - gRadius); activeCtx.lineTo(gx + gRadius, gy); activeCtx.lineTo(gx, gy + gRadius); activeCtx.lineTo(gx - gRadius, gy);
                } else {
                    activeCtx.arc(gx, gy, gRadius, 0, Math.PI * 2);
                }
                activeCtx.closePath();
                activeCtx.fillStyle = 'rgba(6, 182, 212, 0.2)'; // Cyan tint
                activeCtx.fill();
                activeCtx.strokeStyle = '#22d3ee';
                activeCtx.lineWidth = 2 * effectiveScale;
                activeCtx.setLineDash([4 * effectiveScale, 4 * effectiveScale]);
                activeCtx.stroke();
                activeCtx.setLineDash([]);
            });
        }

        // 1. Draw Brightened Lines (Neighbor Hints)
        if (brightenedLines.length > 0) {
            for (const line of brightenedLines) {
                const x1 = line.x1 * spacing + centerOffset; const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset; const y2 = line.y2 * spacing + centerOffset;
                if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

                activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2);
                activeCtx.lineWidth = 1 * effectiveScale;
                activeCtx.strokeStyle = settings.colors[line.limit] || '#666';
                activeCtx.globalAlpha = 0.8; activeCtx.stroke();
            }
        }

        // 2. Draw Active Lines (Strong connection)
        for (const line of activeLines) {
            const x1 = line.x1 * spacing + centerOffset; const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset; const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < cullLeft || Math.min(x1, x2) > cullRight || Math.max(y1, y2) < cullTop || Math.min(y1, y2) > cullBottom) continue;

            activeCtx.beginPath(); activeCtx.moveTo(x1, y1); activeCtx.lineTo(x2, y2);
            activeCtx.lineWidth = 4 * effectiveScale;
            activeCtx.strokeStyle = settings.colors[line.limit] || '#666';
            activeCtx.globalAlpha = 1.0; activeCtx.stroke();
        }

        // 3. Draw Active Nodes (Normal & Phantom)
        for (const [id, activations] of visualLatchedNodes.entries()) {
             // Check both main grid and phantom fallback
             const node = this.cachedNodeMap.get(id) || phantomNodes?.get(id);
             if (!node) continue;

             const isPhantom = !!(phantomNodes?.has(id));

             const x = node.x * spacing + centerOffset; const y = node.y * spacing + centerOffset;
             if (x < cullLeft || x > cullRight || y < cullTop || y > cullBottom) continue;

             const cTop = settings.colors[node.limitTop] || '#666';
             const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
             const radius = Math.max(0, baseRadius * vis.size * settings.latchedZoomScale);

             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius); activeCtx.lineTo(x + radius, y); activeCtx.lineTo(x, y + radius); activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isFlatSkin) {
                 activeCtx.fillStyle = skin.nodeFill(node.limitTop, settings.colors) as string;
             } else {
                 const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
                 grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, settings.colors[node.limitBottom] || '#666');
                 activeCtx.fillStyle = grad;
             }

             // Phantom Visual Style: Reduced Opacity or Dashed Outline
             if (isPhantom) {
                 activeCtx.globalAlpha = 0.5; // "Ghost" look
                 activeCtx.fill();
                 activeCtx.globalAlpha = 1.0;

                 // Draw dashed outline for phantom
                 activeCtx.setLineDash([4 * effectiveScale, 4 * effectiveScale]);
                 activeCtx.strokeStyle = '#fff';
                 activeCtx.lineWidth = 2 * effectiveScale;
                 activeCtx.stroke();
                 activeCtx.setLineDash([]);
             } else {
                 activeCtx.fill();
             }

             const uniqueModes = new Set<number | string>();
             activations.forEach(a => uniqueModes.add(a.mode));
             const sortedModes = Array.from(uniqueModes).sort((a, b) => (MODE_PRIORITY[a] ?? 99) - (MODE_PRIORITY[b] ?? 99));

             sortedModes.forEach((mode, index) => {
                 const color = MODE_COLORS[mode as keyof typeof MODE_COLORS] || '#ffffff';
                 const currentRadius = radius + (2 * effectiveScale) + (index * 6 * effectiveScale);
                 activeCtx.beginPath();
                 if (isDiamond) {
                    activeCtx.moveTo(x, y - currentRadius); activeCtx.lineTo(x + currentRadius, y); activeCtx.lineTo(x, y + currentRadius); activeCtx.lineTo(x - currentRadius, y);
                 } else {
                    activeCtx.arc(x, y, currentRadius, 0, Math.PI * 2);
                 }
                 activeCtx.closePath();
                 activeCtx.strokeStyle = color; activeCtx.lineWidth = 4 * effectiveScale;
                 if (isPhantom) activeCtx.setLineDash([3 * effectiveScale, 3 * effectiveScale]);
                 activeCtx.stroke();
                 activeCtx.setLineDash([]);
             });

             // RE-DRAW TEXT on top of active node
             if (settings.buttonSizeScale * vis.size > 0.4) {
                activeCtx.fillStyle = 'white'; 
                activeCtx.shadowColor = 'black';
                activeCtx.shadowBlur = 4;
                activeCtx.textAlign = 'center'; activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * settings.buttonSizeScale * vis.size * settings.latchedZoomScale)) * settings.nodeTextSizeScale * effectiveScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (settings.showFractionBar) {
                    activeCtx.beginPath(); activeCtx.moveTo(x - (radius * 0.4), y); activeCtx.lineTo(x + (radius * 0.4), y);
                    activeCtx.lineWidth = 1 * effectiveScale; 
                    activeCtx.strokeStyle = 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
                activeCtx.shadowBlur = 0; 
            }
        }
    }
}

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape, PresetSlot, PlaybackMode, LimitType, SynthPreset, GenerationOrigin } from '../types';
import { getPitchRatioFromScreenDelta, PITCH_SCALE } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { LatticeRenderer } from '../services/LatticeRenderer';
import { useLatticeData } from '../hooks/useLatticeData';
import { GRID_CELL_SIZE } from '../constants';
import { reconstructNode } from '../services/LatticeService';

export interface TonalityDiamondHandle {
  clearLatches: (mode?: number) => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => { node: LatticeNode, mode: number }[];
  triggerVisual: (nodeId: string, active: boolean) => void; 
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2 | 3 | 4 | 5 | 6; 
  isCurrentSustainEnabled: boolean;
  globalScale?: number; 
  viewZoom?: number;
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
  onSustainStatusChange?: (activeModes: number[]) => void;
}

interface ActiveCursor {
  pointerId: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  interactionLockedNodeId: string | null;
  isShiftAnchor?: boolean; // Track if this cursor is controlling a chord shift
}

interface NodeActivation {
    mode: number | string; 
    timestamp: number;
    presetId: string;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, isCurrentSustainEnabled, globalScale = 1.0, viewZoom = 1.0, onNodeTrigger, onSustainStatusChange } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const canvasRectRef = useRef<DOMRect | null>(null);

  const animationFrameRef = useRef<number>(0);
  const globalBendRef = useRef<number>(0);
  const rendererRef = useRef<LatticeRenderer>(new LatticeRenderer());

  const effectiveScale = globalScale * viewZoom;
  const prevEffectiveScaleRef = useRef(effectiveScale);

  // --- USE LATTICE DATA HOOK ---
  const {
      data,
      isGenerating,
      nodeMap,
      spatialGrid,
      adjacencyMap,
      dynamicSize,
      centerOffset
  } = useLatticeData(settings, effectiveScale);

  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const prevDynamicSizeRef = useRef(dynamicSize);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, Map<number, number>>>(new Map());
  const [externalTriggers, setExternalTriggers] = useState<Map<string, number>>(new Map()); 
  const nodeTriggerHistory = useRef<Map<string, number>>(new Map());

  // Ref to track sustain state immediately inside pointer handlers without closure staleness
  const isSustainEnabledRef = useRef(isCurrentSustainEnabled);
  useEffect(() => { isSustainEnabledRef.current = isCurrentSustainEnabled; }, [isCurrentSustainEnabled]);

  // Notify parent of active modes
  useEffect(() => {
      if (onSustainStatusChange) {
          const modes = new Set<number>();
          persistentLatches.forEach((modeMap) => {
              modeMap.forEach((_, mode) => modes.add(mode));
          });
          onSustainStatusChange(Array.from(modes));
      }
  }, [persistentLatches, onSustainStatusChange]);

  // Voice Stealing Handler
  useEffect(() => {
      const unsubscribe = audioEngine.onVoiceSteal((voiceId) => {
          if (voiceId.startsWith('node-')) {
              const nodeId = voiceId.replace('node-', '');
              setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                  let changed = false;
                  const next = new Map(prev);
                  if (next.has(nodeId)) {
                      next.delete(nodeId);
                      changed = true;
                  }
                  return changed ? next : prev;
              });
          }
      });
      return unsubscribe;
  }, [audioEngine]);

  // Global Bend Listener
  useEffect(() => {
      const unsubscribe = midiService.onGlobalBend((semitones) => {
          globalBendRef.current = semitones;
      });
      return unsubscribe;
  }, []);

  // Register Chord Presets
  useEffect(() => {
      activeChordIds.forEach(id => {
          const chord = settings.savedChords.find(c => c.id === id);
          if (chord) {
              if (chord.soundConfig) audioEngine.registerPreset(`chord-${id}`, chord.soundConfig);
              if (chord.soundConfigs) {
                  Object.entries(chord.soundConfigs).forEach(([mode, preset]) => {
                      const p = preset as SynthPreset;
                      if (!p) return;
                      const safeId = p.id && String(p.id).startsWith('chord-') 
                          ? String(p.id) 
                          : `chord-${id}-${mode}`;
                      audioEngine.registerPreset(safeId, p);
                  });
              }
          }
      });
  }, [activeChordIds, settings.savedChords, audioEngine]);

  // Aggregates all activations
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, NodeActivation[]>();

      persistentLatches.forEach((modeMap, nodeId) => {
          const activations: NodeActivation[] = [];
          modeMap.forEach((timestamp, mode) => {
              let pId = 'normal';
              if (mode === 1) pId = 'latch';
              else if (mode === 3) pId = 'strum';
              else if (mode === 4) pId = 'brass';
              else if (mode === 5) pId = 'keys';
              else if (mode === 6) pId = 'percussion';
              activations.push({ mode, timestamp, presetId: pId });
          });
          effective.set(nodeId, activations);
      });

      const defaultChordMode = (latchMode === 2) ? 2 : 1; 

      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                let mode = defaultChordMode;
                let presetId = `chord-${chordId}`; 

                if (n.voiceMode) {
                    if (n.voiceMode === 'latch') mode = 1;
                    else if (n.voiceMode === 'normal') mode = 2;
                    else if (n.voiceMode === 'strum') mode = 3;
                    else if (n.voiceMode === 'brass') mode = 4;
                    else if (n.voiceMode === 'keys') mode = 5;
                    else if (n.voiceMode === 'percussion') mode = 6;

                    if (chordDef.soundConfigs && chordDef.soundConfigs[n.voiceMode]) {
                        const specificPreset = chordDef.soundConfigs[n.voiceMode];
                        if (specificPreset?.id && String(specificPreset.id).startsWith('chord-')) {
                            presetId = String(specificPreset.id);
                        } else {
                            presetId = `chord-${chordId}-${n.voiceMode}`;
                        }
                    }
                    else if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = n.voiceMode;
                } else {
                    if (chordDef.soundConfig) presetId = `chord-${chordId}`;
                    else presetId = (latchMode === 2) ? 'normal' : 'latch';
                }

                if (!effective.has(n.id)) effective.set(n.id, []);
                const existing = effective.get(n.id)!;
                if (!existing.some(a => a.mode === mode)) existing.push({ mode, timestamp: 0, presetId });
            });
        }
      });
      effective.forEach((list) => list.sort((a, b) => a.timestamp - b.timestamp));
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, latchMode]);

  // Identify nodes that are active but not present in the current lattice generation (Phantoms)
  // This happens when modulating away from a center but keeping notes latched.
  const phantomNodes = useMemo(() => {
      const phantoms = new Map<string, LatticeNode>();
      audioLatchedNodes.forEach((_, id) => {
          if (!nodeMap.has(id)) {
              // Try to reconstruct the node data from ID
              const node = reconstructNode(id, settings);
              if (node) phantoms.set(id, node);
          }
      });
      // Also check active cursors if they are holding a node that disappeared
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId && !nodeMap.has(cursor.hoverNodeId) && !phantoms.has(cursor.hoverNodeId)) {
              const node = reconstructNode(cursor.hoverNodeId, settings);
              if (node) phantoms.set(cursor.hoverNodeId, node);
          }
      });
      return phantoms;
  }, [audioLatchedNodes, activeCursors, nodeMap, settings]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map<string, NodeActivation[]>();
      audioLatchedNodes.forEach((v, k) => visual.set(k, [...v]));

      activeCursors.forEach(cursor => {
          const isSustainingInstrument = latchMode >= 1; 
          const isSustainActive = isCurrentSustainEnabled;
          const isBendEnabled = settings.isPitchBendEnabled;
          const isShiftMode = settings.isShiftModeActive;
          const isModulating = settings.isModulationModeActive;

          if (isModulating) return;

          // Determine if we should show cursor glow
          const showCursor = !isShiftMode && (isBendEnabled || !isSustainingInstrument || !isSustainActive || cursor.isShiftAnchor);

          if (showCursor && cursor.hoverNodeId) {
              const nodeId = cursor.hoverNodeId;
              if (!visual.has(nodeId)) visual.set(nodeId, []);
              const list = visual.get(nodeId)!;
              const activation = { mode: latchMode, timestamp: Date.now(), presetId: 'cursor' };
              list.push(activation);
              list.sort((a, b) => a.timestamp - b.timestamp);
          }
      });

      // Add External Triggers (Arp)
      externalTriggers.forEach((timestamp, nodeId) => {
          if (!visual.has(nodeId)) visual.set(nodeId, []);
          const list = visual.get(nodeId)!;
          list.push({ mode: 'arp', timestamp, presetId: 'arpeggio' });
      });

      return visual;
  }, [audioLatchedNodes, activeCursors, settings.isPitchBendEnabled, settings.isModulationModeActive, settings.isShiftModeActive, latchMode, isCurrentSustainEnabled, externalTriggers]);

  // Calculate predicted "Ghost" nodes for Shift Mode
  const shiftGhostNodes = useMemo(() => {
      const ghosts = new Map<string, LatticeNode>();
      if (!settings.isShiftModeActive) return ghosts;

      // Find an active shift anchor
      let anchorCursor: ActiveCursor | null = null;
      for (const c of activeCursors.values()) {
          if (c.isShiftAnchor && c.originNodeId && c.hoverNodeId) {
              anchorCursor = c;
              break;
          }
      }

      if (anchorCursor && anchorCursor.originNodeId && anchorCursor.hoverNodeId) {
          const anchorNode = nodeMap.get(anchorCursor.originNodeId) || phantomNodes.get(anchorCursor.originNodeId);
          const targetNode = nodeMap.get(anchorCursor.hoverNodeId) || phantomNodes.get(anchorCursor.hoverNodeId);

          if (anchorNode && targetNode && anchorNode.id !== targetNode.id) {
              // Calculate vector
              const diffCoords = targetNode.coords.map((c, i) => c - anchorNode.coords[i]);
              const diffOctave = targetNode.octave - anchorNode.octave;

              // Apply to all latched nodes
              visualLatchedNodes.forEach((_, sourceId) => {
                  const sourceNode = nodeMap.get(sourceId) || phantomNodes.get(sourceId);
                  if (sourceNode) {
                      const newCoords = sourceNode.coords.map((c, i) => c + (diffCoords[i] || 0));
                      const newOct = sourceNode.octave + diffOctave;
                      const newId = `${newCoords.join(',')}:${newOct}`;

                      // Check existing first, else reconstruct
                      const existing = nodeMap.get(newId);
                      if (existing) {
                          ghosts.set(newId, existing);
                      } else {
                          // Allow Phantom Ghosts
                          const ghost = reconstructNode(newId, settings);
                          if (ghost) ghosts.set(newId, ghost);
                      }
                  }
              });
          }
      }
      return ghosts;
  }, [settings.isShiftModeActive, activeCursors, visualLatchedNodes, nodeMap, phantomNodes, settings]);

  // Calculate Harmonic Neighbors for Highlighting
  const harmonicNeighbors = useMemo(() => {
      const neighbors = new Map<string, number>();
      const activeIds = new Set<string>();

      activeCursors.forEach(c => { if(c.hoverNodeId) activeIds.add(c.hoverNodeId); });
      visualLatchedNodes.forEach((_, id) => activeIds.add(id));

      if (activeIds.size === 0) return neighbors;

      activeIds.forEach(sourceId => {
          const adj = adjacencyMap.get(sourceId);
          if (adj) {
              adj.forEach(edge => {
                  // Filter for consonance (Limit 3 and 5)
                  if (edge.limit <= 5 && !activeIds.has(edge.target)) {
                      const current = neighbors.get(edge.target) || 99;
                      if (edge.limit < current) neighbors.set(edge.target, edge.limit);
                  }
              });
          }
      });
      return neighbors;
  }, [activeCursors, visualLatchedNodes, adjacencyMap]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;
    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            if (latched.has(line.sourceId) && latched.has(line.targetId)) active.push(line);
        }
    } 
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).map(id => nodeMap.get(id) || phantomNodes.get(id)).filter(n => n) as LatticeNode[];
        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];
                let coordDist = 0;
                for (let k=0; k < A.coords.length; k++) coordDist += Math.abs(A.coords[k] - B.coords[k]);
                const octaveDist = Math.abs(A.octave - B.octave);
                const totalDist = coordDist + octaveDist;

                if (totalDist <= 2) {
                    let lineLimit = Math.max(A.maxPrime, B.maxPrime);
                    if (coordDist === 0 && octaveDist !== 0) lineLimit = LimitType.LIMIT_2;
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y, x2: B.x, y2: B.y,
                        limit: lineLimit, 
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap, phantomNodes]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      data.lines.forEach(line => {
          if (activeIds.has(line.sourceId) || activeIds.has(line.targetId)) {
              resultLines.add(line);
              if (activeIds.has(line.sourceId)) step1Neighbors.add(line.targetId);
              if (activeIds.has(line.targetId)) step1Neighbors.add(line.sourceId);
          }
      });

      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              if (step1Neighbors.has(line.sourceId) || step1Neighbors.has(line.targetId)) resultLines.add(line);
          });
      }
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const shiftGhostNodesRef = useRef(shiftGhostNodes); 
  const phantomNodesRef = useRef(phantomNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const harmonicNeighborsRef = useRef(harmonicNeighbors);
  const effectiveScaleRef = useRef(effectiveScale);
  const latchModeRef = useRef(latchMode);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const persistentLatchesRef = useRef<Map<string, Map<number, number>>>(persistentLatches);
  const audioLatchedNodesRef = useRef(audioLatchedNodes);
  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
  const centerOffsetRef = useRef(centerOffset);

  useLayoutEffect(() => { settingsRef.current = settings; }, [settings]);
  useLayoutEffect(() => { dataRef.current = data; }, [data]);
  useLayoutEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useLayoutEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useLayoutEffect(() => { shiftGhostNodesRef.current = shiftGhostNodes; }, [shiftGhostNodes]);
  useLayoutEffect(() => { phantomNodesRef.current = phantomNodes; }, [phantomNodes]);
  useLayoutEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useLayoutEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useLayoutEffect(() => { harmonicNeighborsRef.current = harmonicNeighbors; }, [harmonicNeighbors]);
  useLayoutEffect(() => { effectiveScaleRef.current = effectiveScale; }, [effectiveScale]);
  useLayoutEffect(() => { latchModeRef.current = latchMode; }, [latchMode]);
  useLayoutEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useLayoutEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useLayoutEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
  useLayoutEffect(() => { audioLatchedNodesRef.current = audioLatchedNodes; }, [audioLatchedNodes]);
  useLayoutEffect(() => { centerOffsetRef.current = centerOffset; }, [centerOffset]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  const updateRect = () => {
      if (scrollContainerRef.current) {
          canvasRectRef.current = scrollContainerRef.current.getBoundingClientRect();
      }
  };

  useEffect(() => {
      window.addEventListener('resize', updateRect);
      const scroller = scrollContainerRef.current;
      if (scroller) scroller.addEventListener('scroll', updateRect);
      updateRect();
      return () => {
          window.removeEventListener('resize', updateRect);
          if (scroller) scroller.removeEventListener('scroll', updateRect);
      };
  }, []);

  useImperativeHandle(ref, () => ({
    clearLatches: (mode?: number) => {
        if (mode === undefined) setPersistentLatches(new Map());
        else {
            setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                const next = new Map();
                prev.forEach((modeMap, nodeId) => {
                    const newModeMap = new Map(modeMap);
                    if (newModeMap.has(mode)) newModeMap.delete(mode);
                    if (newModeMap.size > 0) next.set(nodeId, newModeMap);
                });
                return next;
            });
        }
    },
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13|15];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: { node: LatticeNode, mode: number }[] = [];
        persistentLatches.forEach((modeMap, id) => {
            const n = nodeMap.get(id) || phantomNodes.get(id);
            if (n) {
                modeMap.forEach((_, mode) => result.push({ node: n, mode }));
            }
        });
        return result;
    },
    triggerVisual: (nodeId: string, active: boolean) => {
        setExternalTriggers(prev => {
            const next = new Map(prev);
            if (active) next.set(nodeId, Date.now());
            else next.delete(nodeId);
            return next;
        });
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = centerOffset - viewportW / 2;
        scrollContainerRef.current.scrollTop = centerOffset - viewportH / 2;
        requestAnimationFrame(updateRect);
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          requestAnimationFrame(centerScroll);
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad]);

  // Adjust scroll position when dynamic size changes to keep view centered relative to content
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
        requestAnimationFrame(updateRect);
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  useLayoutEffect(() => {
      const container = scrollContainerRef.current;
      if (!container) return;

      const oldScale = prevEffectiveScaleRef.current;
      const newScale = effectiveScale;

      if (oldScale !== newScale && oldScale > 0) {
          const viewW = container.clientWidth;
          const viewH = container.clientHeight;

          const oldSpacing = settingsRef.current.buttonSpacingScale * oldScale;
          const newSpacing = settingsRef.current.buttonSpacingScale * newScale;

          const currentScrollLeft = container.scrollLeft;
          const currentScrollTop = container.scrollTop;

          const centerX_from_origin = (currentScrollLeft + viewW / 2) - centerOffset;
          const centerY_from_origin = (currentScrollTop + viewH / 2) - centerOffset;

          const normX = centerX_from_origin / oldSpacing;
          const normY = centerY_from_origin / oldSpacing;

          const newCenterX_from_origin = normX * newSpacing;
          const newCenterY_from_origin = normY * newSpacing;

          container.scrollLeft = (newCenterX_from_origin + centerOffset) - viewW / 2;
          container.scrollTop = (newCenterY_from_origin + centerOffset) - viewH / 2;

          requestAnimationFrame(updateRect);
      }

      prevEffectiveScaleRef.current = newScale;
  }, [effectiveScale]);


  const prevAudioLatchedRef = useRef<Map<string, NodeActivation[]>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      const nodes = nodeMap;
      const phantoms = phantomNodes;

      current.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const prevActivations = prev.get(nodeId);
              const wasActive = prevActivations && prevActivations.some(p => p.mode === act.mode);

              if (!wasActive) {
                   const node = nodes.get(nodeId) || phantoms.get(nodeId); 
                   if (node) {
                       audioEngine.startVoice(voiceId, node.ratio, settings.baseFrequency, act.presetId, 'latch');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
              }
          });
      });

      prev.forEach((activations, nodeId) => {
          activations.forEach(act => {
              const voiceId = `node-${nodeId}-${act.mode}`;
              const currentActivations = current.get(nodeId);
              const stillActive = currentActivations && currentActivations.some(c => c.mode === act.mode);

              if (!stillActive) {
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          });
      });

      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, phantomNodes, settings.baseFrequency, settings.midiEnabled]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!scrollContainerRef.current) return null;
      const rect = scrollContainerRef.current.getBoundingClientRect();

      const bend = globalBendRef.current;
      const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;

      const scrollLeft = scrollContainerRef.current.scrollLeft;
      const scrollTop = scrollContainerRef.current.scrollTop;

      const viewportX = clientX - rect.left;
      const viewportY = clientY - rect.top;

      const x = viewportX + scrollLeft;
      const y = (viewportY - pixelOffset) + scrollTop;

      const spacing = settings.buttonSpacingScale * effectiveScale;
      const baseRadius = (60 * settings.buttonSizeScale * effectiveScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;
      const latchedMap = visualLatchedRef.current;
      const zoomScale = settingsRef.current.latchedZoomScale;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;

                  const isLatched = latchedMap.has(node.id);
                  const activeZoom = isLatched ? zoomScale : 1.0;
                  const activeRadius = baseRadius * activeZoom;

                  // Simple circle hit test
                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < activeRadius*activeRadius) return node;
              }
          }
      }
      return null;
  };

  const getVoiceParams = (mode: number, isStrumEnabled: boolean): { preset: PresetSlot, playback: PlaybackMode } => {
      switch(mode) {
          case 1: return { preset: 'latch', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 2: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 3: return { preset: 'strum', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 4: return { preset: 'brass', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 5: return { preset: 'keys', playback: isStrumEnabled ? 'trigger' : 'gate' };
          case 6: return { preset: 'percussion', playback: isStrumEnabled ? 'trigger' : 'gate' };
          default: return { preset: 'normal', playback: isStrumEnabled ? 'trigger' : 'gate' };
      }
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (audioEngine) audioEngine.resume();

      if (uiUnlocked) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      updateRect();

      let canvasPos = { x: e.clientX, y: e.clientY };
      cursorPositionsRef.current.set(e.pointerId, canvasPos);

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (hitNode) {
        // --- MODULATION LOGIC ---
        if (settings.isModulationModeActive) {
            const newOrigin: GenerationOrigin = {
                coords: hitNode.coords,
                octave: hitNode.octave
            };

            const newPath = [...settings.modulationPath, newOrigin];

            const currentOrigin = settings.modulationPath[settings.modulationPath.length - 1];
            const isSame = currentOrigin.coords.every((v, i) => v === hitNode.coords[i]) && currentOrigin.octave === hitNode.octave;

            if (!isSame) {
                updateSettings({ 
                    modulationPath: newPath,
                    isModulationModeActive: false
                });
            }
            return; 
        }

        // --- SHIFT LOGIC (Initiate) ---
        const isShiftMode = settings.isShiftModeActive;
        const currentLatches = persistentLatchesRef.current;
        const isClickedLatched = currentLatches.has(hitNode.id);

        if (isShiftMode && isClickedLatched) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: true // Mark as anchor
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            return; // Don't trigger sound or normal latch logic
        }

        nodeTriggerHistory.current.set(hitNode.id, Date.now());

        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isSustainingInstrument = latchMode >= 1;
        const isSustainActive = isCurrentSustainEnabled;
        const isBendEnabled = settings.isPitchBendEnabled; 

        if (isSustainingInstrument && isSustainActive && !isShiftMode) {
             setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                 const next = new Map(prev);
                 const nodeModes = next.get(hitNode.id) || new Map<number, number>();

                 if (nodeModes.has(latchMode)) {
                     nodeModes.delete(latchMode);
                 } else {
                     nodeModes.set(latchMode, Date.now());
                 }

                 if (nodeModes.size > 0) next.set(hitNode.id, nodeModes);
                 else next.delete(hitNode.id);
                 return next;
             });
        }

        if ((isBendEnabled || !isSustainActive) && !isShiftMode) {
             const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false,
                interactionLockedNodeId: null,
                isShiftAnchor: false
            };

            const nextRef = new Map(activeCursorsRef.current);
            nextRef.set(e.pointerId, newCursor);
            activeCursorsRef.current = nextRef;

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                return next;
            });

            const { preset, playback } = getVoiceParams(latchMode, settings.isStrumEnabled);
            const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

            audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, preset, playback);
            if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      } else {
          const newCursor: ActiveCursor = {
              pointerId: e.pointerId,
              originNodeId: null, 
              hoverNodeId: null,
              hasMoved: false,
              interactionLockedNodeId: null,
              isShiftAnchor: false
          };
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.set(e.pointerId, newCursor);
              return next;
          });
          activeCursorsRef.current.set(e.pointerId, newCursor);
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    let worldY = e.clientY;
    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        const bend = globalBendRef.current;
        const pixelOffset = -bend * (PITCH_SCALE / 12) * effectiveScale;
        worldY = (e.clientY - r.top) - pixelOffset + scrollContainerRef.current.scrollTop;
    }

    if (scrollContainerRef.current) {
        const r = scrollContainerRef.current.getBoundingClientRect();
        cursorPositionsRef.current.set(e.pointerId, { 
            x: e.clientX - r.left + scrollContainerRef.current.scrollLeft, 
            y: e.clientY - r.top + scrollContainerRef.current.scrollTop 
        });
    }

    let hasMoved = cursor.hasMoved;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

    const isSustainingInstrument = latchMode >= 1;
    const isSustainActive = isSustainEnabledRef.current;
    const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
    const isShiftMode = settingsRef.current.isShiftModeActive;

    // --- SHIFT LOGIC (Glide) ---
    if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
         const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
         if (anchorNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (anchorNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const glideRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);

             // Glide ALL latched voices
             audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     const targetRatio = node.ratio * glideRatio;
                     activations.forEach(act => {
                         const voiceId = `node-${nodeId}-${act.mode}`;
                         audioEngine.glideVoice(voiceId, targetRatio, settingsRef.current.baseFrequency);
                     });
                 }
             });
         }
         // Continue to allow update of hoverNodeId for ghosting logic
    }

    // --- BEND LOGIC ---
    const isBending = isBendEnabled && !!cursor.originNodeId && !isShiftMode;

    if (isBending && dynamicCanvasRef.current) {
         const originNode = nodeMapRef.current.get(cursor.originNodeId!) || phantomNodesRef.current.get(cursor.originNodeId!);
         if (originNode) {
             const spacing = settingsRef.current.buttonSpacingScale * effectiveScale;
             const originWorldY = (originNode.y * spacing) + centerOffset;
             const currentDeltaY = worldY - originWorldY;
             const bentRatio = getPitchRatioFromScreenDelta(currentDeltaY, settingsRef.current.buttonSpacingScale * effectiveScale);
             const finalRatio = originNode.ratio * bentRatio;

             const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
             audioEngine.glideVoice(voiceId, finalRatio, settingsRef.current.baseFrequency);
             if (settingsRef.current.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
         }
    }

    let nextInteractionLock = cursor.interactionLockedNodeId;
    let shouldUpdateState = false;

    if (hitNode) {
         if (isSustainingInstrument && isSustainActive && isBendEnabled && !isShiftMode) {
             if (cursor.interactionLockedNodeId !== hitNode.id) {
                 const currentModes = persistentLatchesRef.current.get(hitNode.id);
                 const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                 if (!isAlreadyLatched) {
                     setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                         const next = new Map(prev);
                         const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                         nodeModes.set(latchMode, Date.now());
                         next.set(hitNode.id, nodeModes);
                         return next;
                     });
                     nodeTriggerHistory.current.set(hitNode.id, Date.now());
                     nextInteractionLock = hitNode.id;
                     shouldUpdateState = true;
                 }
             }
         }
    }

    if (cursor.hoverNodeId !== hitId) {
        shouldUpdateState = true;
        nextInteractionLock = null;

        const isLeavingOrigin = cursor.hoverNodeId === cursor.originNodeId;
        const shouldSustainBend = isBending && isLeavingOrigin;

        if (!shouldSustainBend && cursor.hoverNodeId) {
             if (playback === 'gate') {
                 const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                 audioEngine.stopVoice(oldVoiceId);
                 if (settingsRef.current.midiEnabled) midiService.noteOff(oldVoiceId);
             }
        }

        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

             // Combined Latch Logic: Triggers if Sustain is Active, regardless of Bend status
             // This logic allows latches to form while dragging if Sustain is toggled mid-drag
             if (isSustainingInstrument && isSustainActive && !isShiftMode) {
                const isDifferentNode = hitNode.id !== cursor.originNodeId;
                if (hasMoved || isDifferentNode) {
                    const currentModes = persistentLatchesRef.current.get(hitNode.id);
                    const isAlreadyLatched = currentModes && currentModes.has(latchMode);

                    if (!isAlreadyLatched) { 
                        setPersistentLatches((prev: Map<string, Map<number, number>>) => {
                            const next = new Map(prev);
                            const nodeModes = next.get(hitNode.id) || new Map<number, number>();
                            nodeModes.set(latchMode, Date.now());
                            next.set(hitNode.id, nodeModes);
                            return next;
                        });
                        nodeTriggerHistory.current.set(hitNode.id, Date.now());
                    }
                }
             } 
             else if (!isBending && !isShiftMode) {
                 nodeTriggerHistory.current.set(hitNode.id, Date.now());

                 const { preset, playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);
                 const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;

                 audioEngine.startVoice(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, preset, playback);
                 if (settingsRef.current.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settingsRef.current.baseFrequency, settingsRef.current.midiPitchBendRange);
             }
        }
    }

    if (shouldUpdateState || (hasMoved !== cursor.hasMoved)) {
        const updatedCursor = { 
            ...cursor, 
            hoverNodeId: hitId, 
            hasMoved: hasMoved, 
            interactionLockedNodeId: nextInteractionLock 
        };

        activeCursorsRef.current.set(e.pointerId, updatedCursor);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, updatedCursor);
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;
        const { playback } = getVoiceParams(latchMode, settingsRef.current.isStrumEnabled);

        const isBendEnabled = settingsRef.current.isPitchBendEnabled; 
        const isShiftMode = settingsRef.current.isShiftModeActive;
        const isSustainActive = isSustainEnabledRef.current;

        // --- SHIFT LOGIC (Commit) ---
        if (isShiftMode && cursor.isShiftAnchor && cursor.originNodeId) {
            const anchorNode = nodeMapRef.current.get(cursor.originNodeId) || phantomNodesRef.current.get(cursor.originNodeId);
            const targetNode = nodeMapRef.current.get(cursor.hoverNodeId || "") || phantomNodesRef.current.get(cursor.hoverNodeId || "");

            // Re-center pitch of original voices immediately (reset glide)
            audioLatchedNodesRef.current.forEach((activations, nodeId) => {
                 const node = nodeMapRef.current.get(nodeId) || phantomNodesRef.current.get(nodeId);
                 if (node) {
                     activations.forEach(act => {
                         audioEngine.glideVoice(`node-${nodeId}-${act.mode}`, node.ratio, settingsRef.current.baseFrequency);
                     });
                 }
            });

            if (anchorNode && targetNode && anchorNode.id !== targetNode.id) {
                // Calculate transposition vector in coordinate space
                // Diff: Target - Anchor
                const diffCoords = targetNode.coords.map((c, i) => c - anchorNode.coords[i]);
                const diffOctave = targetNode.octave - anchorNode.octave;

                const newLatches = new Map<string, Map<number, number>>();

                // If Move (Sustain Off), start with empty map. If Copy (Sustain On), start with existing.
                if (isSustainActive) {
                    persistentLatchesRef.current.forEach((v, k) => newLatches.set(k, v));
                }

                // Iterate originals and transpose
                persistentLatchesRef.current.forEach((modes, sourceId) => {
                    const sourceNode = nodeMapRef.current.get(sourceId) || phantomNodesRef.current.get(sourceId);
                    if (sourceNode) {
                        // Apply Vector
                        const newCoords = sourceNode.coords.map((c, i) => c + (diffCoords[i] || 0));
                        const newOct = sourceNode.octave + diffOctave;
                        const newId = `${newCoords.join(',')}:${newOct}`;

                        // NOTE: We allow "Phantom Nodes". 
                        // If the node exists in the map, great. If not, we still allow it.
                        // The phantomNodes logic will pick it up on next render.

                        // Merge modes
                        const targetModes = newLatches.get(newId) || new Map<number, number>();
                        modes.forEach((ts, m) => targetModes.set(m, Date.now()));
                        newLatches.set(newId, targetModes);
                    }
                });

                setPersistentLatches(newLatches);
            }
        } 
        // --- NORMAL LOGIC ---
        else {
            if (cursor.originNodeId && isBendEnabled && !isShiftMode) {
                const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                audioEngine.stopVoice(voiceId);
                if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
            }
            else if (cursor.hoverNodeId) {
                 if (playback === 'gate') {
                     const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                     audioEngine.stopVoice(voiceId);
                     if (settingsRef.current.midiEnabled) midiService.noteOff(voiceId);
                 }
            }
        }

        cursorPositionsRef.current.delete(e.pointerId);
        const nextRef = new Map(activeCursorsRef.current);
        nextRef.delete(e.pointerId);
        activeCursorsRef.current = nextRef;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const staticCanvas = staticCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      const scroller = scrollContainerRef.current;

      const currentScale = effectiveScaleRef.current; 

      if (!bgCanvas || !staticCanvas || !activeCanvas || !scroller) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const viewX = scroller.scrollLeft;
      const viewY = scroller.scrollTop;
      const viewW = scroller.clientWidth;
      const viewH = scroller.clientHeight;

      rendererRef.current.render(
          bgCanvas,
          staticCanvas,
          activeCanvas,
          {
              data: dataRef.current,
              settings: settingsRef.current,
              visualLatchedNodes: visualLatchedRef.current, 
              activeLines: activeLinesRef.current,
              brightenedLines: brightenedLinesRef.current,
              harmonicNeighbors: harmonicNeighborsRef.current, 
              activeCursors: activeCursorsRef.current,
              cursorPositions: cursorPositionsRef.current,
              nodeTriggerHistory: nodeTriggerHistory.current,
              globalBend: globalBendRef.current,
              effectiveScale: effectiveScaleRef.current,
              centerOffset: centerOffsetRef.current,
              view: { x: viewX, y: viewY, w: viewW, h: viewH },
              time: time,
              latchMode: latchModeRef.current,
              phantomNodes: phantomNodesRef.current,
              shiftGhostNodes: shiftGhostNodesRef.current // Pass map of ghosts
          }
      );

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyles = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;
      const isJIOverride = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice' && settings.layoutApproach !== 'diamond';

      const baseStyle: React.CSSProperties = {
          position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%', 
          pointerEvents: 'none',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', 
          backgroundSize: 'cover',
          backgroundColor: 'black' 
      };

      if (isJIOverride) {
          return { base: baseStyle };
      }

      switch (mode) {
          case 'gradient': {
              const type = settings.gradientType === 'radial' ? 'radial-gradient' : 'linear-gradient';
              const direction = settings.gradientType === 'linear' ? `${settings.gradientAngle}deg,` : 'circle at center,';
              const start = settings.gradientColorStart || '#000000';
              const end = settings.gradientColorEnd || '#000000';
              baseStyle.backgroundImage = `${type}(${direction} ${start}, ${end})`;
              baseStyle.backgroundColor = 'transparent'; 
              break;
          }
          case 'image': {
              if (settings.backgroundImageData) {
                  const tint = settings.bgImageTint || '#000000';
                  const strength = settings.bgImageTintStrength || 0;

                  const hexToRgba = (hex: string, alpha: number) => {
                      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                      return result ? `rgba(${parseInt(result[1], 16)},${parseInt(result[2], 16)},${parseInt(result[3], 16)},${alpha})` : 'rgba(0,0,0,0)';
                  };

                  const tintRgba = hexToRgba(tint, strength);
                  baseStyle.backgroundImage = `linear-gradient(${tintRgba}, ${tintRgba}), url("${settings.backgroundImageData}")`;
                  baseStyle.backgroundColor = 'transparent'; 

                  baseStyle.backgroundRepeat = settings.backgroundTiling ? 'repeat' : 'no-repeat';
                  baseStyle.backgroundSize = settings.backgroundTiling ? 'auto' : 'cover'; 

                  if (settings.bgImageGamma !== 1.0) {
                      baseStyle.filter = `brightness(${settings.bgImageGamma})`;
                  }
              }
              break;
          }
          case 'solid':
          default: {
              baseStyle.backgroundColor = settings.solidColor || '#ffffff';
              baseStyle.backgroundImage = 'none';
              break;
          }
      }

      return { base: baseStyle };
  };

  const bgStyles = getBackgroundStyles();

  return (
    <div 
        ref={scrollContainerRef} 
        className="w-full h-full overflow-auto relative bg-black" 
        style={{ touchAction: 'none' }} 
        onPointerDown={handlePointerDown} 
        onPointerMove={handlePointerMove} 
        onPointerUp={handlePointerUp} 
        onPointerLeave={handlePointerUp} 
        onPointerCancel={handlePointerUp}
    >
        {/* Fixed Layer for Background and Canvases */}
        <div className="sticky top-0 left-0 w-full h-full z-0 overflow-hidden pointer-events-none">
             {/* Background */}
             <div style={bgStyles.base} className="absolute inset-0 w-full h-full z-0" />

             {/* Canvas Layers */}
             <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 w-full h-full z-[5]" />
             <canvas ref={staticCanvasRef} className="absolute top-0 left-0 w-full h-full z-[10]" />
             <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 w-full h-full z-[20]" />

             {isGenerating && (
                <div className="fixed top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl pointer-events-none">
                    <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
                    <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
                </div>
            )}
        </div>

        {/* Scroll Spacer */}
        <div style={{ width: dynamicSize, height: dynamicSize, pointerEvents: 'none' }} />
    </div>
  );
});

